# ============================================================
#  STAGE A — data.  Resumable: a completed stage is restored from Drive
#  in about three minutes instead of being recomputed in twenty.
# ============================================================
import os, sys, glob, json, time, zipfile, urllib.request, subprocess, warnings
warnings.filterwarnings("ignore")
from google.colab import drive
drive.mount("/content/drive", force_remount=False)

DRIVE = "/content/drive/MyDrive/dhide_ckpt"
os.makedirs(DRIVE, exist_ok=True)
print("checkpoint folder:", DRIVE)
print("contents:", sorted(os.listdir(DRIVE)) or "empty")

subprocess.run([sys.executable, "-m", "pip", "-q", "install", "jpegio", "h5py"], check=False)
import numpy as np, torch, cv2, jpegio, h5py
print("torch", torch.__version__, "| GPU:",
      torch.cuda.get_device_name(0) if torch.cuda.is_available() else "NONE  <-- set T4")

TAR = f"{DRIVE}/data.tar.gz"
if os.path.exists(TAR):
    print("\nrestoring converted data from Drive ...", flush=True)
    t0 = time.time()
    subprocess.run(["tar", "xzf", TAR, "-C", "/content"], check=True)
    print(f"  restored {len(glob.glob('/content/data/jpeg_qf75/*.jpg'))} images "
          f"in {time.time()-t0:.0f}s")
else:
    print("\nno cached data; downloading from figshare ...", flush=True)
    os.makedirs("/content/zips", exist_ok=True); os.makedirs("/content/mats", exist_ok=True)
    files = json.loads(urllib.request.urlopen(
        "https://api.figshare.com/v2/articles/1512427/files").read())
    for f in [x for x in files if x["name"].lower().endswith(".zip")]:
        dst = f"/content/zips/{f['name']}"
        if os.path.exists(dst) and os.path.getsize(dst) == f["size"]:
            print("  cached", f["name"]); continue
        t0 = time.time(); urllib.request.urlretrieve(f["download_url"], dst)
        print(f"  {f['name']} {os.path.getsize(dst)/1e6:.0f} MB in {time.time()-t0:.0f}s", flush=True)
    for z in sorted(glob.glob("/content/zips/*.zip")):
        with zipfile.ZipFile(z) as zf: zf.extractall("/content/mats")
    n = len(glob.glob("/content/mats/**/*.mat", recursive=True))
    print(f"  unpacked {n} .mat files"); assert n > 3000

    exec(open("/content/gate_core.py").read())
    print("\nconverting ...", flush=True)
    rows = convert("/content/mats", "/content/data")
    json.dump(rows, open("/content/data/rows.json", "w"))
    print(f"  {len(rows)} slices, {len({r[1] for r in rows})} patients")

    print("\narchiving to Drive (one file, not 9000) ...", flush=True)
    t0 = time.time()
    subprocess.run(["tar", "czf", TAR, "-C", "/content", "data"], check=True)
    print(f"  {os.path.getsize(TAR)/1e6:.0f} MB in {time.time()-t0:.0f}s")

exec(open("/content/gate_core.py").read())
rows = [tuple(r) for r in json.load(open("/content/data/rows.json"))]
df, clean = split_by_patient(rows)
assert clean, "patient overlap"
print("\nSTAGE A complete")
print(df.groupby(["split", "label_name"]).size().unstack(fill_value=0))

# ============================================================
#  STAGE B — the frozen surrogate.  Restored from Drive if present.
# ============================================================
import os, torch, torch.nn as nn
from torchvision import models
from torch.utils.data import DataLoader

CKPT_D = f"{DRIVE}/resnet50.pt"
if os.path.exists(CKPT_D):
    print("restoring the trained model from Drive ...")
    net = models.resnet50(weights=None); net.fc = nn.Linear(net.fc.in_features, 3)
    net.load_state_dict(torch.load(CKPT_D, map_location=DEV))
    net = net.to(DEV).eval()
    for p in net.parameters(): p.requires_grad_(False)
else:
    print("training ResNet-50, about forty minutes ...", flush=True)
    net, best = train_cad(df, "/content/data", qf=75, epochs=15, bs=32,
                          ckpt="/content/resnet50.pt")
    torch.save(net.state_dict(), CKPT_D)
    print(f"saved to Drive, best validation {best:.4f}")

acc, auc = evaluate(net, DataLoader(DS(df[df.split == "test"], "/content/data", 75, False),
                                    batch_size=32))
print(f"\nSTAGE B complete — test accuracy {acc:.4f}, AUC {auc:.4f}")
print("previous run gave 0.9375 / 0.9847; a match confirms the split was reproduced")

# ============================================================
#  TABLE 9 (revised) — cost-axis ablation with paired metrics
#
#  Delta-AUC is a set-level statistic and discards the pairing between a
#  cover and its own stego image, which left the first run with a noise
#  floor comparable to the tolerance. Every primary metric here is paired:
#  each image is compared with itself.
#
#  Primary  : mean |delta p| of the cover-predicted class
#             prediction flip rate
#  Secondary: delta AUC, file-size growth
#  Testing  : Wilcoxon signed-rank, config 7 (D+R+G) against config 4 (D+R)
#
#  The sweep runs to completion instead of stopping at the first violation,
#  so the rate at which the constraint begins to bind is observable.
#  ~45 min for 120 images.
# ============================================================
import sys, os, gc, json, time, traceback, warnings
sys.path.insert(0, "/content")
import numpy as np, cv2, jpegio, torch
from scipy.stats import wilcoxon
from sklearn.metrics import roc_auc_score
import embed_core as E
warnings.filterwarnings("ignore")

ROOT, QF, EPS, DMAX, N_IMG = "/content/data", 75, 0.005, 2.0, 120
RATES = [0.05, 0.10, 0.20, 0.30, 0.40, 0.50]
rng = np.random.default_rng(42)
_t = df[df.split == "test"]
sub = _t.sample(min(N_IMG, len(_t)), random_state=42)
paths = [f"{ROOT}/jpeg_qf{QF}/{s}.jpg" for s in sub.slice_id]
labels = np.asarray(sub.label.values) - 1

print("global rate table ...", flush=True)
TAB = E.rate_table(paths[:20], per_img=150)

print("caching cost maps ...", flush=True)
CACHE = {}
for i, p in enumerate(paths):
    j = jpegio.read(p)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    Q = j.quant_tables[0].astype(float); del j; gc.collect()
    CACHE[p] = dict(D=E.ranknorm(E.rho_D(Q, C.shape)),
                    R=E.ranknorm(E.rho_R(TAB, C.shape)),
                    G=E.ranknorm(rho_G(net, cv2.imread(p, cv2.IMREAD_GRAYSCALE), Q)),
                    n=len(E.carrier(C)[0]))
    if (i + 1) % 40 == 0: print(f"  {i+1}/{len(paths)}", flush=True)

@torch.no_grad()
def probs(files):
    P = []
    for k in range(0, len(files), 32):
        xs = [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in files[k:k+32]]
        P.append(torch.softmax(net(torch.cat(xs)), 1).cpu().numpy())
    return np.vstack(P)

P0 = probs(paths)
CLS0 = P0.argmax(1)
AUC0 = roc_auc_score(labels, P0, multi_class="ovr", average="macro", labels=[0, 1, 2])
print(f"\nclean cover: AUC {AUC0:.4f}, accuracy {(CLS0 == labels).mean():.4f}\n", flush=True)

CFG = [("1", 1, 0, 0), ("2", 0, 1, 0), ("3", 0, 0, 1), ("4", 1, 1, 0),
       ("5", 1, 0, 1), ("6", 0, 1, 1), ("7", 1, 1, 1), ("8", "rand", 0, 0)]
grid, per_image, t0 = [], {}, time.time()

for name, wd, wr, wg in CFG:
    for rate in RATES:
        outs, sizes, failed = [], [], 0
        for p in paths:
            c = CACHE[p]
            rho = (rng.random(c["D"].shape) if wd == "rand"
                   else (wd * c["D"] + wr * c["R"] + wg * c["G"]) / max(wd + wr + wg, 1))
            m = int(rate * c["n"])
            o = f"/tmp/s_{os.path.basename(p)}"
            try:
                st = E.embed(p, o, rng.integers(0, 2, m).astype(np.uint8), rho)
                outs.append(o); sizes.append(st["size_pct"])
            except Exception as ex:
                failed += 1
                if failed == 1:
                    print(f"    [cfg {name} rate {rate}] {type(ex).__name__}: {ex}", flush=True)
        if len(outs) < 0.9 * len(paths):
            print(f"  cfg {name} rate {rate}: {failed} failures, skipped", flush=True); continue
        idx = [i for i, p in enumerate(paths) if f"/tmp/s_{os.path.basename(p)}" in outs]
        P1 = probs(outs)
        dp = np.abs(P1[np.arange(len(idx)), CLS0[idx]] - P0[idx, CLS0[idx]])
        flip = (P1.argmax(1) != CLS0[idx]).astype(float)
        dauc = AUC0 - roc_auc_score(labels[idx], P1, multi_class="ovr",
                                    average="macro", labels=[0, 1, 2])
        rec = dict(cfg=name, rate=rate, mean_dp=float(dp.mean()), sd_dp=float(dp.std()),
                   flip=float(flip.mean()), dauc=float(dauc), size=float(np.mean(sizes)),
                   n=len(idx), feasible=bool(dauc <= EPS and np.mean(sizes) <= DMAX))
        grid.append(rec); per_image[f"{name}@{rate}"] = dp.tolist()
        print(f"  cfg {name} rate {rate:.2f} | mean|dp| {dp.mean():.5f} | flip {100*flip.mean():5.2f}% "
              f"| dAUC {dauc:+.4f} | size {np.mean(sizes):+.2f}% "
              f"| {'ok' if rec['feasible'] else 'VIOLATED'}", flush=True)
        for o in outs: os.remove(o)
    print(f"  --- config {name} done [{time.time()-t0:.0f}s]\n", flush=True)

# paired test: the contribution (7) against the state of the art (4)
tests = {}
for rate in RATES:
    a, b = per_image.get(f"7@{rate}"), per_image.get(f"4@{rate}")
    if a and b and len(a) == len(b):
        a, b = np.asarray(a), np.asarray(b)
        s, p = wilcoxon(a, b)
        d = np.sign(a - b); cliff = float((d < 0).mean() - (d > 0).mean())
        tests[rate] = dict(mean_7=float(a.mean()), mean_4=float(b.mean()),
                           p=float(p), cliff_delta=cliff)

c = CACHE[paths[0]]; m = int(0.2 * c["n"]); bits = rng.integers(0, 2, m).astype(np.uint8)
E.embed(paths[0], "/tmp/chk.jpg", bits, (c["D"] + c["R"] + c["G"]) / 3)
ber = float(np.mean(bits != E.extract("/tmp/chk.jpg", m)))

json.dump(dict(auc_clean=float(AUC0), eps=EPS, n_images=N_IMG, ber=ber,
               grid=grid, tests=tests), open("/content/table9b.json", "w"), indent=2)

print("=" * 78)
print(f"{'cfg':>4} {'rate':>5} {'mean|dp|':>10} {'flip%':>7} {'dAUC':>9} {'size%':>7} {'ok':>4}")
for r in grid:
    print(f"{r['cfg']:>4} {r['rate']:>5.2f} {r['mean_dp']:>10.5f} {100*r['flip']:>7.2f} "
          f"{r['dauc']:>+9.4f} {r['size']:>+7.2f} {'y' if r['feasible'] else 'n':>4}")
print("\nWilcoxon, config 7 (D+R+G) vs config 4 (D+R), paired on |delta p|")
for rate, v in tests.items():
    print(f"  rate {rate:.2f}: mean 7 = {v['mean_7']:.5f}, mean 4 = {v['mean_4']:.5f}, "
          f"p = {v['p']:.2e}, Cliff delta = {v['cliff_delta']:+.3f}")
print(f"\nclean AUC {AUC0:.4f} | bit error rate {ber:.4f}")
print("=" * 78)
print(open("/content/table9b.json").read()[:1200])

# ============================================================
#  CELL B — Unified detectability: one protocol for Tables 6, 8 and 9
#
#  Every arm embeds IDENTICAL payload bits (rng restarted at each arm) into
#  the same 80 slices, and is scored by the same DCTR detector with the same
#  folds. P(E) and the classifier disturbance on those 80 slices come from
#  this single run, so the three tables can no longer disagree.
#
#  RUN FIRST: the RESTORE cell. Resumable per seed.
#  SEEDS = [42] takes about 2 h on a T4. Five seeds take about 10 h; add them
#  later if time allows, the cell skips seeds already on Drive.
