# ---- single inference pipeline, used for reference metrics and experiments
import torch.nn.functional as F

def to_tensor(img8):
    """512x512 in, resized to the training resolution inside, so gradients
    still reach the full-resolution pixels the DCT coefficients control."""
    x = torch.from_numpy(img8.astype(np.float32) / 255.)[None, None].repeat(1, 3, 1, 1)
    x = (x.to(DEV) - MEAN) / STD
    return F.interpolate(x, (224, 224), mode="bilinear",
                         align_corners=False, antialias=True)

# reference metrics under this pipeline, for Table 3
import numpy as np, cv2, json
from sklearn.metrics import roc_auc_score, f1_score
te = df[df.split == "test"]
paths = [f"/content/data/jpeg_qf75/{s}.jpg" for s in te.slice_id]
lab = np.asarray(te.label.values) - 1
P = []
with torch.no_grad():
    for k in range(0, len(paths), 32):
        P.append(torch.softmax(net(torch.cat(
            [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in paths[k:k+32]])), 1).cpu().numpy())
P = np.vstack(P); pred = P.argmax(1)
ref = dict(acc=float((pred == lab).mean()),
           auc=float(roc_auc_score(lab, P, multi_class="ovr", average="macro", labels=[0,1,2])),
           f1=float(f1_score(lab, pred, average="weighted")),
           sens=[float((pred[lab == k] == k).mean()) for k in range(3)])
json.dump(ref, open("/content/ref_resnet50.json", "w"), indent=2)
print("ResNet-50 reference under the unified pipeline:")
print(f"  accuracy {ref['acc']:.4f} | AUC {ref['auc']:.4f} | F1 {ref['f1']:.4f}")
print(f"  sensitivity men/gli/pit: {ref['sens'][0]:.3f} / {ref['sens'][1]:.3f} / {ref['sens'][2]:.3f}")
print("\nthis is now the reference for Table 3. rerun the ablation cell next.")

