# ============================================================
#  TABLE 9 — cost-axis ablation with paired metrics
#  Primary  : mean |delta p| of the cover-predicted class, prediction flip rate
#  Secondary: delta AUC, file-size growth
#  Testing  : Wilcoxon signed-rank, config 7 (D+R+G) against config 4 (D+R)
#  ~45 min for 120 images.
# ============================================================
import sys, os, gc, json, time, warnings
sys.path.insert(0, "/content")
import numpy as np, cv2, jpegio, torch
from scipy.stats import wilcoxon
from sklearn.metrics import roc_auc_score
import embed_core as E
warnings.filterwarnings("ignore")

ROOT, QF, EPS, DMAX, N_IMG = "/content/data", 75, 0.005, 2.0, 120
RATES = [0.05, 0.10, 0.20, 0.30]
rng = np.random.default_rng(42)
_t = df[df.split == "test"]
sub = _t.sample(min(N_IMG, len(_t)), random_state=42)
paths = [f"{ROOT}/jpeg_qf{QF}/{s}.jpg" for s in sub.slice_id]
labels = np.asarray(sub.label.values) - 1

print("global rate table ...", flush=True)
TAB = E.rate_table(paths[:20], per_img=150)

print("caching cost maps ...", flush=True)
CACHE = {}
for i, p in enumerate(paths):
    j = jpegio.read(p)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    Q = j.quant_tables[0].astype(float); del j; gc.collect()
    CACHE[p] = dict(D=E.ranknorm(E.rho_D(Q, C.shape)),
                    R=E.ranknorm(E.rho_R(TAB, C.shape)),
                    G=E.ranknorm(rho_G(net, cv2.imread(p, cv2.IMREAD_GRAYSCALE), Q)),
                    n=len(E.carrier(C)[0]))
    if (i + 1) % 40 == 0: print(f"  {i+1}/{len(paths)}", flush=True)

@torch.no_grad()
def probs(files):
    P = []
    for k in range(0, len(files), 32):
        xs = [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in files[k:k+32]]
        P.append(torch.softmax(net(torch.cat(xs)), 1).cpu().numpy())
    return np.vstack(P)

P0 = probs(paths)
CLS0 = P0.argmax(1)
AUC0 = roc_auc_score(labels, P0, multi_class="ovr", average="macro", labels=[0, 1, 2])
print(f"\nclean cover: AUC {AUC0:.4f}, accuracy {(CLS0 == labels).mean():.4f}", flush=True)
assert (CLS0 == labels).mean() > 0.80, "resolution mismatch: redefine to_tensor first"
print()

CFG = [("1", 1, 0, 0), ("2", 0, 1, 0), ("3", 0, 0, 1), ("4", 1, 1, 0),
       ("5", 1, 0, 1), ("6", 0, 1, 1), ("7", 1, 1, 1), ("8", "rand", 0, 0)]
grid, per_image, t0 = [], {}, time.time()

for name, wd, wr, wg in CFG:
    for rate in RATES:
        outs, sizes, failed = [], [], 0
        for p in paths:
            c = CACHE[p]
            rho = (rng.random(c["D"].shape) if wd == "rand"
                   else (wd * c["D"] + wr * c["R"] + wg * c["G"]) / max(wd + wr + wg, 1))
            m = int(rate * c["n"])
            o = f"/tmp/s_{os.path.basename(p)}"
            try:
                st = E.embed(p, o, rng.integers(0, 2, m).astype(np.uint8), rho)
                outs.append(o); sizes.append(st["size_pct"])
            except Exception as ex:
                failed += 1
                if failed == 1:
                    print(f"    [cfg {name} rate {rate}] {type(ex).__name__}: {ex}", flush=True)
        if len(outs) < 0.9 * len(paths):
            print(f"  cfg {name} rate {rate}: {failed} failures, skipped", flush=True); continue
        idx = [i for i, p in enumerate(paths) if f"/tmp/s_{os.path.basename(p)}" in outs]
        P1 = probs(outs)
        dp = np.abs(P1[np.arange(len(idx)), CLS0[idx]] - P0[idx, CLS0[idx]])
        flip = (P1.argmax(1) != CLS0[idx]).astype(float)
        dauc = AUC0 - roc_auc_score(labels[idx], P1, multi_class="ovr",
                                    average="macro", labels=[0, 1, 2])
        rec = dict(cfg=name, rate=rate, mean_dp=float(dp.mean()), sd_dp=float(dp.std()),
                   flip=float(flip.mean()), dauc=float(dauc), size=float(np.mean(sizes)),
                   n=len(idx), feasible=bool(dauc <= EPS and np.mean(sizes) <= DMAX))
        grid.append(rec); per_image[f"{name}@{rate}"] = dp.tolist()
        print(f"  cfg {name} rate {rate:.2f} | mean|dp| {dp.mean():.5f} | flip {100*flip.mean():5.2f}% "
              f"| dAUC {dauc:+.4f} | size {np.mean(sizes):+.2f}% "
              f"| {'ok' if rec['feasible'] else 'VIOLATED'}", flush=True)
        for o in outs: os.remove(o)
    print(f"  --- config {name} done [{time.time()-t0:.0f}s]\n", flush=True)

tests = {}
for rate in RATES:
    a, b = per_image.get(f"7@{rate}"), per_image.get(f"4@{rate}")
    if a and b and len(a) == len(b):
        a, b = np.asarray(a), np.asarray(b)
        s, p = wilcoxon(a, b)
        d = np.sign(a - b); cliff = float((d < 0).mean() - (d > 0).mean())
        tests[rate] = dict(mean_7=float(a.mean()), mean_4=float(b.mean()),
                           reduction_pct=float(100 * (1 - a.mean() / b.mean())),
                           p=float(p), cliff_delta=cliff)

c = CACHE[paths[0]]; m = int(0.2 * c["n"]); bits = rng.integers(0, 2, m).astype(np.uint8)
E.embed(paths[0], "/tmp/chk.jpg", bits, (c["D"] + c["R"] + c["G"]) / 3)
ber = float(np.mean(bits != E.extract("/tmp/chk.jpg", m)))

json.dump(dict(auc_clean=float(AUC0), acc_clean=float((CLS0 == labels).mean()),
               eps=EPS, n_images=N_IMG, ber=ber, grid=grid, tests=tests),
          open("/content/table9c.json", "w"), indent=2)

print("=" * 78)
print(f"{'cfg':>4} {'rate':>5} {'mean|dp|':>10} {'flip%':>7} {'dAUC':>9} {'size%':>7} {'ok':>4}")
for r in grid:
    print(f"{r['cfg']:>4} {r['rate']:>5.2f} {r['mean_dp']:>10.5f} {100*r['flip']:>7.2f} "
          f"{r['dauc']:>+9.4f} {r['size']:>+7.2f} {'y' if r['feasible'] else 'n':>4}")
print("\nWilcoxon, config 7 (D+R+G) vs config 4 (D+R), paired on |delta p|")
for rate, v in tests.items():
    print(f"  rate {rate:.2f}: 7 = {v['mean_7']:.5f}, 4 = {v['mean_4']:.5f}, "
          f"reduction {v['reduction_pct']:+.1f}%, p = {v['p']:.2e}, Cliff = {v['cliff_delta']:+.3f}")
print(f"\nclean AUC {AUC0:.4f} | accuracy {(CLS0 == labels).mean():.4f} | BER {ber:.4f}")
print("=" * 78)
print(open("/content/table9c.json").read()[:900])

# ---- redefine rho_G so the gradient reaches the 512x512 pixels ----------
import torch.nn.functional as F
from scipy.fftpack import dct

def _prep512(img8):
    """Normalised 512x512 tensor. Gradients are taken with respect to this."""
    x = torch.from_numpy(img8.astype(np.float32) / 255.)[None, None].repeat(1, 3, 1, 1)
    return (x.to(DEV) - MEAN) / STD

def _forward(x512):
    """Resize inside the graph, so autograd carries the gradient back to x512."""
    return net(F.interpolate(x512, (224, 224), mode="bilinear",
                             align_corners=False, antialias=True))

def to_tensor(img8):
    """Inference path. Same operator as _forward, for consistency."""
    return F.interpolate(_prep512(img8), (224, 224), mode="bilinear",
                         align_corners=False, antialias=True)

def rho_G(net_, img8, Q):
    """Equation (9): |Q .* DCT8x8(grad_x Phi)| at full 512x512 resolution."""
    x = _prep512(img8).requires_grad_(True)
    out = _forward(x)
    cls = int(out.argmax(1))
    net_.zero_grad()
    out[0, cls].backward()
    g = x.grad[0].sum(0).detach().cpu().numpy()          # 512 x 512
    H, W = g.shape
    nb = H // 8
    b = g.reshape(nb, 8, W // 8, 8).transpose(0, 2, 1, 3)
    G = np.abs(dct(dct(b, axis=2, norm="ortho"), axis=3, norm="ortho") * Q)
    return G.transpose(0, 2, 1, 3).reshape(H, W)

# verify shapes and that the gradient is non-trivial
import cv2, jpegio, numpy as np
p = f"/content/data/jpeg_qf75/{df[df.split=='test'].slice_id.iloc[0]}.jpg"
j = jpegio.read(p); Q = j.quant_tables[0].astype(float); del j
G = rho_G(net, cv2.imread(p, cv2.IMREAD_GRAYSCALE), Q)
print("rho_G shape:", G.shape, "| expected (512, 512)")
print(f"range {G.min():.3e} .. {G.max():.3e} | nonzero {100*(G>0).mean():.1f}%")
print("to_tensor shape:", tuple(to_tensor(cv2.imread(p, cv2.IMREAD_GRAYSCALE)).shape),
      "| expected (1, 3, 224, 224)")

# ============================================================
#  RERUN — Table 4 (gate) and Table 5 (map validation)
#  Both were measured with a model running at 512x512, outside the
#  resolution it was trained on. This repeats them under the corrected
#  pipeline. ~35 min.
# ============================================================
import os, gc, json, tempfile, warnings
import numpy as np, cv2, jpegio, torch
from scipy.stats import spearmanr
warnings.filterwarnings("ignore")

ROOT, N_IMG, N_PROBE = "/content/data", 50, 40
rng = np.random.default_rng(42)
_t = df[df.split == "test"]
sub = _t.sample(min(N_IMG, len(_t)), random_state=42)

# sanity: the corrected pipeline must be in force
_p = f"{ROOT}/jpeg_qf75/{sub.slice_id.iloc[0]}.jpg"
assert tuple(to_tensor(cv2.imread(_p, cv2.IMREAD_GRAYSCALE)).shape) == (1, 3, 224, 224), \
    "to_tensor is not the corrected version"
_j = jpegio.read(_p); _Q = _j.quant_tables[0].astype(float); del _j
assert rho_G(net, cv2.imread(_p, cv2.IMREAD_GRAYSCALE), _Q).shape == (512, 512), \
    "rho_G is not the corrected version"
print("corrected pipeline confirmed\n")


# ---------- Table 4: the three cost axes ---------------------------------
print("TABLE 4 — cost-axis correlations", flush=True)
res4, pooled = {}, {"D": [], "R": [], "G": []}
for qf in (50, 75, 90):
    acc = {"D": [], "R": [], "G": []}
    for _, row in sub.iterrows():
        jpg = f"{ROOT}/jpeg_qf{qf}/{row.slice_id}.jpg"
        if not os.path.exists(jpg): continue
        j = jpegio.read(jpg)
        C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
        Q = j.quant_tables[0].astype(float); del j; gc.collect()
        base = os.path.getsize(jpg)
        G = rho_G(net, cv2.imread(jpg, cv2.IMREAD_GRAYSCALE), Q)
        nz = np.argwhere(C != 0)
        if len(nz) < 50: continue
        sel = nz[rng.choice(len(nz), min(400, len(nz)), replace=False)]
        for r, c in sel:
            jj = jpegio.read(jpg); jj.coef_arrays[0][r, c] += 1
            t = tempfile.mktemp(suffix=".jpg"); jpegio.write(jj, t)
            acc["R"].append(os.path.getsize(t) - base); os.remove(t)
            acc["D"].append(float(Q[r % 8, c % 8]) ** 2)
            acc["G"].append(float(G[r, c]))
    for k in acc:
        acc[k] = np.asarray(acc[k]); pooled[k].append(acc[k])
    n = len(acc["D"]); res4[f"n_{qf}"] = n
    for a, b in (("D", "R"), ("D", "G"), ("R", "G")):
        res4[f"{a}{b}_{qf}"] = float(spearmanr(acc[a], acc[b])[0])
    R = acc["R"]
    res4[f"rate_{qf}"] = [float(R.min()), float(R.max()), float(R.mean()),
                          float((R == 0).mean())]
    print(f"  QF {qf}: n={n}  rho(D,R)={res4[f'DR_{qf}']:+.3f}  "
          f"rho(D,G)={res4[f'DG_{qf}']:+.3f}  rho(R,G)={res4[f'RG_{qf}']:+.3f}", flush=True)
P = {k: np.concatenate(v) for k, v in pooled.items()}
for a, b in (("D", "R"), ("D", "G"), ("R", "G")):
    res4[f"{a}{b}_all"] = float(spearmanr(P[a], P[b])[0])
res4["n_all"] = len(P["D"])
print(f"  pooled: n={res4['n_all']}  rho(D,G)={res4['DG_all']:+.3f}\n", flush=True)


# ---------- Table 5: validation of the map -------------------------------
print("TABLE 5 — sensitivity map validation", flush=True)
from scipy.fftpack import dct
import torch.nn.functional as F

_feat, _grad = {}, {}
_tg = net.layer4[-1]
_h1 = _tg.register_forward_hook(lambda m, i, o: _feat.__setitem__("v", o))
_h2 = _tg.register_full_backward_hook(lambda m, gi, go: _grad.__setitem__("v", go[0]))

def grad_cam(img8):
    x = _prep512(img8).requires_grad_(True)
    out = _forward(x); cls = int(out.argmax(1))
    net.zero_grad(); out[0, cls].backward()
    f, g = _feat["v"][0], _grad["v"][0]
    return torch.relu((g.mean(dim=(1, 2), keepdim=True) * f).sum(0)).detach().cpu().numpy()

def bpool(a, n):
    s = a.shape[0] // n
    return a.reshape(n, s, n, s).sum(axis=(1, 3))

def signed_map(img8, Q):
    x = _prep512(img8).requires_grad_(True)
    out = _forward(x); cls = int(out.argmax(1))
    net.zero_grad(); out[0, cls].backward()
    g = x.grad[0].sum(0).detach().cpu().numpy()
    nb = g.shape[0] // 8
    b = g.reshape(nb, 8, nb, 8).transpose(0, 2, 1, 3)
    S = dct(dct(b, axis=2, norm="ortho"), axis=3, norm="ortho") * Q
    return S.transpose(0, 2, 1, 3).reshape(g.shape), cls

sgn, absl, dice, iou, mass, blk, cam_r = [], [], [], [], [], [], []
for k, (_, row) in enumerate(sub.iterrows(), 1):
    jpg = f"{ROOT}/jpeg_qf75/{row.slice_id}.jpg"
    mp = f"{ROOT}/masks/{row.slice_id}.png"
    if not (os.path.exists(jpg) and os.path.exists(mp)): continue
    j = jpegio.read(jpg)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    Q = j.quant_tables[0].astype(float); del j; gc.collect()
    img8 = cv2.imread(jpg, cv2.IMREAD_GRAYSCALE)
    S, cls = signed_map(img8, Q); G = np.abs(S)
    with torch.no_grad():
        l0 = float(net(to_tensor(img8))[0][cls])
    nz = np.argwhere(C != 0)
    sel = nz[rng.choice(len(nz), min(N_PROBE, len(nz)), replace=False)]
    d = []
    for r, c in sel:
        jj = jpegio.read(jpg); jj.coef_arrays[0][r, c] += 1
        t = tempfile.mktemp(suffix=".jpg"); jpegio.write(jj, t)
        with torch.no_grad():
            d.append(float(net(to_tensor(cv2.imread(t, cv2.IMREAD_GRAYSCALE)))[0][cls]) - l0)
        os.remove(t)
    d = np.asarray(d); pr = S[sel[:, 0], sel[:, 1]]
    if d.std() > 0 and pr.std() > 0:
        sgn.append(spearmanr(pr, d)[0]); absl.append(spearmanr(abs(pr), abs(d))[0])

    mask = cv2.imread(mp, cv2.IMREAD_GRAYSCALE) > 127
    nb = 64
    tum = mask.reshape(nb, 8, nb, 8).transpose(0, 2, 1, 3).reshape(nb, nb, 64).any(2)
    gb = bpool(G, nb)
    if tum.sum() > 0:
        hot = gb >= np.percentile(gb, 100 * (1 - tum.mean()))
        inter = float((hot & tum).sum())
        dice.append(2 * inter / max(hot.sum() + tum.sum(), 1))
        iou.append(inter / max((hot | tum).sum(), 1))
        mass.append(gb[tum].sum() / max(gb.sum(), 1e-12)); blk.append(tum.mean())

    cam = grad_cam(img8); n = cam.shape[0]
    gs = bpool(G, n).ravel()
    if cam.std() > 0 and gs.std() > 0:
        cam_r.append(spearmanr(gs, cam.ravel())[0])
    if k % 10 == 0: print(f"  {k}/{len(sub)}", flush=True)

_h1.remove(); _h2.remove()
res5 = dict(signed=float(np.mean(sgn)), signed_sd=float(np.std(sgn)),
            absolute=float(np.mean(absl)), absolute_sd=float(np.std(absl)),
            dice=float(np.mean(dice)), dice_sd=float(np.std(dice)),
            iou=float(np.mean(iou)), mass=float(np.mean(mass)),
            blkfrac=float(np.mean(blk)), gradcam=float(np.mean(cam_r)),
            gradcam_sd=float(np.std(cam_r)), n=len(dice))
res5["concentration"] = res5["mass"] / max(res5["blkfrac"], 1e-9)

json.dump(dict(table4=res4, table5=res5), open("/content/tables45_fixed.json", "w"), indent=2)
print("\n" + "=" * 70)
print("TABLE 4")
print(f"{'QF':>5} {'n':>7} {'rho(D,R)':>10} {'rho(D,G)':>10} {'rho(R,G)':>10}")
for qf in (50, 75, 90):
    print(f"{qf:>5} {res4[f'n_{qf}']:>7} {res4[f'DR_{qf}']:>+10.3f} "
          f"{res4[f'DG_{qf}']:>+10.3f} {res4[f'RG_{qf}']:>+10.3f}")
print(f"{'all':>5} {res4['n_all']:>7} {res4['DR_all']:>+10.3f} "
      f"{res4['DG_all']:>+10.3f} {res4['RG_all']:>+10.3f}")
for qf in (50, 75, 90):
    lo, hi, mu, z = res4[f"rate_{qf}"]
    print(f"  rate QF {qf}: min {lo:+.0f}  max {hi:+.0f}  mean {mu:+.3f}  no effect {100*z:.1f}%")
print("\nTABLE 5")
print(f"  signed probe   : {res5['signed']:+.3f} +/- {res5['signed_sd']:.3f}  (threshold 0.70)")
print(f"  absolute probe : {res5['absolute']:+.3f} +/- {res5['absolute_sd']:.3f}")
print(f"  Dice           : {res5['dice']:.3f} +/- {res5['dice_sd']:.3f}")
print(f"  IoU            : {res5['iou']:.3f}")
print(f"  Grad-CAM       : {res5['gradcam']:+.3f} +/- {res5['gradcam_sd']:.3f}")
print(f"  mass in tumour : {100*res5['mass']:.1f}%   tumour blocks {100*res5['blkfrac']:.1f}%")
print(f"  concentration  : {res5['concentration']:.2f}x")
print("=" * 70)
print(open("/content/tables45_fixed.json").read())

