import os, gc, json, tempfile, warnings
import numpy as np, cv2, jpegio, torch
import torch.nn.functional as F
from scipy.fftpack import dct
from scipy.stats import spearmanr
warnings.filterwarnings("ignore")

assert "res4" in dir(), "res4 was lost; rerun the previous cell"
ROOT, N_PROBE, NB = "/content/data", 40, 64
rng = np.random.default_rng(42)

_feat, _grad = {}, {}
_tg = net.layer4[-1]
_h1 = _tg.register_forward_hook(lambda m, i, o: _feat.__setitem__("v", o))
_h2 = _tg.register_full_backward_hook(lambda m, gi, go: _grad.__setitem__("v", go[0]))

def grad_cam_64(img8):
    """Grad-CAM is 7x7 at a 224 input. Resample it to the 64x64 block grid
    so it can be compared with the coefficient map on equal terms."""
    x = _prep512(img8).requires_grad_(True)
    out = _forward(x); cls = int(out.argmax(1))
    net.zero_grad(); out[0, cls].backward()
    f, g = _feat["v"][0], _grad["v"][0]
    cam = torch.relu((g.mean(dim=(1, 2), keepdim=True) * f).sum(0))
    cam = F.interpolate(cam[None, None], size=(NB, NB), mode="bilinear",
                        align_corners=False)[0, 0]
    return cam.detach().cpu().numpy()

def bpool64(a):
    return a.reshape(NB, 8, NB, 8).sum(axis=(1, 3))

def signed_map(img8, Q):
    x = _prep512(img8).requires_grad_(True)
    out = _forward(x); cls = int(out.argmax(1))
    net.zero_grad(); out[0, cls].backward()
    g = x.grad[0].sum(0).detach().cpu().numpy()
    nb = g.shape[0] // 8
    b = g.reshape(nb, 8, nb, 8).transpose(0, 2, 1, 3)
    S = dct(dct(b, axis=2, norm="ortho"), axis=3, norm="ortho") * Q
    return S.transpose(0, 2, 1, 3).reshape(g.shape), cls

sgn, absl, dice, iou, mass, blk, cam_r = [], [], [], [], [], [], []
for k, (_, row) in enumerate(sub.iterrows(), 1):
    jpg = f"{ROOT}/jpeg_qf75/{row.slice_id}.jpg"
    mp = f"{ROOT}/masks/{row.slice_id}.png"
    if not (os.path.exists(jpg) and os.path.exists(mp)): continue
    j = jpegio.read(jpg)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    Q = j.quant_tables[0].astype(float); del j; gc.collect()
    img8 = cv2.imread(jpg, cv2.IMREAD_GRAYSCALE)
    S, cls = signed_map(img8, Q); G = np.abs(S)

    with torch.no_grad():
        l0 = float(net(to_tensor(img8))[0][cls])
    nz = np.argwhere(C != 0)
    sel = nz[rng.choice(len(nz), min(N_PROBE, len(nz)), replace=False)]
    d = []
    for r, c in sel:
        jj = jpegio.read(jpg); jj.coef_arrays[0][r, c] += 1
        t = tempfile.mktemp(suffix=".jpg"); jpegio.write(jj, t)
        with torch.no_grad():
            d.append(float(net(to_tensor(cv2.imread(t, cv2.IMREAD_GRAYSCALE)))[0][cls]) - l0)
        os.remove(t)
    d = np.asarray(d); pr = S[sel[:, 0], sel[:, 1]]
    if d.std() > 0 and pr.std() > 0:
        sgn.append(spearmanr(pr, d)[0]); absl.append(spearmanr(abs(pr), abs(d))[0])

    mask = cv2.imread(mp, cv2.IMREAD_GRAYSCALE) > 127
    tum = mask.reshape(NB, 8, NB, 8).transpose(0, 2, 1, 3).reshape(NB, NB, 64).any(2)
    gb = bpool64(G)
    if tum.sum() > 0:
        hot = gb >= np.percentile(gb, 100 * (1 - tum.mean()))
        inter = float((hot & tum).sum())
        dice.append(2 * inter / max(hot.sum() + tum.sum(), 1))
        iou.append(inter / max((hot | tum).sum(), 1))
        mass.append(gb[tum].sum() / max(gb.sum(), 1e-12)); blk.append(tum.mean())

    cam = grad_cam_64(img8)
    if cam.std() > 0 and gb.std() > 0:
        cam_r.append(spearmanr(gb.ravel(), cam.ravel())[0])
    if k % 10 == 0: print(f"  {k}/{len(sub)}", flush=True)

_h1.remove(); _h2.remove()
res5 = dict(signed=float(np.mean(sgn)), signed_sd=float(np.std(sgn)),
            absolute=float(np.mean(absl)), absolute_sd=float(np.std(absl)),
            dice=float(np.mean(dice)), dice_sd=float(np.std(dice)),
            iou=float(np.mean(iou)), mass=float(np.mean(mass)),
            blkfrac=float(np.mean(blk)), gradcam=float(np.mean(cam_r)),
            gradcam_sd=float(np.std(cam_r)), n=len(dice))
res5["concentration"] = res5["mass"] / max(res5["blkfrac"], 1e-9)

json.dump(dict(table4=res4, table5=res5), open("/content/tables45_fixed.json", "w"), indent=2)
print("\n" + "=" * 70)
print("TABLE 4")
print(f"{'QF':>5} {'n':>7} {'rho(D,R)':>10} {'rho(D,G)':>10} {'rho(R,G)':>10}")
for qf in (50, 75, 90):
    print(f"{qf:>5} {res4[f'n_{qf}']:>7} {res4[f'DR_{qf}']:>+10.3f} "
          f"{res4[f'DG_{qf}']:>+10.3f} {res4[f'RG_{qf}']:>+10.3f}")
print(f"{'all':>5} {res4['n_all']:>7} {res4['DR_all']:>+10.3f} "
      f"{res4['DG_all']:>+10.3f} {res4['RG_all']:>+10.3f}")
for qf in (50, 75, 90):
    lo, hi, mu, z = res4[f"rate_{qf}"]
    print(f"  rate QF {qf}: min {lo:+.0f}  max {hi:+.0f}  mean {mu:+.3f}  no effect {100*z:.1f}%")
print("\nTABLE 5")
print(f"  signed probe   : {res5['signed']:+.3f} +/- {res5['signed_sd']:.3f}  (threshold 0.70)")
print(f"  absolute probe : {res5['absolute']:+.3f} +/- {res5['absolute_sd']:.3f}")
print(f"  Dice           : {res5['dice']:.3f} +/- {res5['dice_sd']:.3f}")
print(f"  IoU            : {res5['iou']:.3f}")
print(f"  Grad-CAM       : {res5['gradcam']:+.3f} +/- {res5['gradcam_sd']:.3f}")
print(f"  mass in tumour : {100*res5['mass']:.1f}%   tumour blocks {100*res5['blkfrac']:.1f}%")
print(f"  concentration  : {res5['concentration']:.2f}x")
print("=" * 70)
print(open("/content/tables45_fixed.json").read())

# ============================================================
#  Tables 3 and 7 — held-out architectures and transfer
#
#  The optimiser sees only ResNet-50. If the 60 percent reduction is a
#  property of that network rather than of the criterion, it will not
#  survive on models the optimiser never touched. Embedding is performed
#  with the ResNet-50 sensitivity map and evaluated on all three.
#  ~60 min: two models to train, then the transfer sweep.
# ============================================================
import os, gc, json, time, warnings
import numpy as np, cv2, jpegio, torch, torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import DataLoader
from torchvision import models
from scipy.stats import wilcoxon
from sklearn.metrics import roc_auc_score, f1_score
import embed_core as E
warnings.filterwarnings("ignore")

ROOT, QF = "/content/data", 75
DRIVE = "/content/drive/MyDrive/dhide_ckpt"
os.makedirs(DRIVE, exist_ok=True)
rng = np.random.default_rng(42)

def build(arch):
    m = getattr(models, arch)(weights="DEFAULT")
    if hasattr(m, "fc"):
        m.fc = nn.Linear(m.fc.in_features, 3)
    elif isinstance(m.classifier, nn.Sequential):
        last = [x for x in m.classifier if isinstance(x, nn.Linear)][-1]
        m.classifier[-1] = nn.Linear(last.in_features, 3)
    else:
        m.classifier = nn.Linear(m.classifier.in_features, 3)
    return m.to(DEV)

# ---------- train or restore the two held-out models ----------------------
NETS = {"resnet50": net}
for arch in ["efficientnet_b0", "densenet121"]:
    ck = f"{DRIVE}/{arch}.pt"
    m = build(arch)
    if os.path.exists(ck):
        m.load_state_dict(torch.load(ck, map_location=DEV))
        print(f"{arch}: restored from Drive", flush=True)
    else:
        print(f"training {arch} ...", flush=True)
        tr, va = df[df.split == "train"], df[df.split == "val"]
        dl_tr = DataLoader(DS(tr, ROOT, QF, True), batch_size=32, shuffle=True, num_workers=2)
        dl_va = DataLoader(DS(va, ROOT, QF, False), batch_size=32, num_workers=2)
        cnt = tr.label.value_counts().reindex([1, 2, 3]).fillna(0).values
        w = torch.tensor((cnt.sum() / np.maximum(cnt, 1)) / 3, dtype=torch.float32, device=DEV)
        opt = torch.optim.AdamW(m.parameters(), lr=1e-4, weight_decay=1e-4)
        sch = torch.optim.lr_scheduler.CosineAnnealingLR(opt, 15)
        lf, best = nn.CrossEntropyLoss(weight=w), -1
        for ep in range(1, 16):
            m.train()
            for x, y in dl_tr:
                x, y = x.to(DEV), y.to(DEV)
                opt.zero_grad(); lf(m(x), y).backward(); opt.step()
            sch.step()
            a, u = evaluate(m, dl_va)
            if u > best: best = u; torch.save(m.state_dict(), ck)
            print(f"  epoch {ep:02d}  val acc {a:.4f}  auc {u:.4f}", flush=True)
        m.load_state_dict(torch.load(ck, map_location=DEV))
    m.eval()
    for p in m.parameters(): p.requires_grad_(False)
    NETS[arch] = m

# ---------- Table 3: reference metrics under the unified pipeline ---------
def infer(model, files):
    P = []
    with torch.no_grad():
        for k in range(0, len(files), 32):
            xs = [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in files[k:k+32]]
            P.append(torch.softmax(model(torch.cat(xs)), 1).cpu().numpy())
    return np.vstack(P)

te = df[df.split == "test"]
te_paths = [f"{ROOT}/jpeg_qf{QF}/{s}.jpg" for s in te.slice_id]
te_lab = np.asarray(te.label.values) - 1
table3 = {}
print("\nTable 3 — reference performance")
for name, m in NETS.items():
    P = infer(m, te_paths); pred = P.argmax(1)
    table3[name] = dict(
        acc=float((pred == te_lab).mean()),
        auc=float(roc_auc_score(te_lab, P, multi_class="ovr", average="macro", labels=[0,1,2])),
        f1=float(f1_score(te_lab, pred, average="weighted")),
        sens=[float((pred[te_lab == k] == k).mean()) for k in range(3)])
    v = table3[name]
    print(f"  {name:16s} acc {v['acc']:.4f} | AUC {v['auc']:.4f} | F1 {v['f1']:.4f} | "
          f"sens {v['sens'][0]:.3f}/{v['sens'][1]:.3f}/{v['sens'][2]:.3f}", flush=True)

# ---------- Table 7: transfer, configs 4 and 7 at two payload rates -------
N_IMG, RATES = 120, [0.05, 0.10]
sub = te.sample(min(N_IMG, len(te)), random_state=42)
paths = [f"{ROOT}/jpeg_qf{QF}/{s}.jpg" for s in sub.slice_id]

print("\ncaching cost maps (ResNet-50 surrogate only) ...", flush=True)
TAB = E.rate_table(paths[:20], per_img=150)
CACHE = {}
for i, p in enumerate(paths):
    j = jpegio.read(p)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    Q = j.quant_tables[0].astype(float); del j; gc.collect()
    CACHE[p] = dict(D=E.ranknorm(E.rho_D(Q, C.shape)),
                    R=E.ranknorm(E.rho_R(TAB, C.shape)),
                    G=E.ranknorm(rho_G(net, cv2.imread(p, cv2.IMREAD_GRAYSCALE), Q)),
                    n=len(E.carrier(C)[0]))
    if (i + 1) % 40 == 0: print(f"  {i+1}/{len(paths)}", flush=True)

BASE = {nm: infer(m, paths) for nm, m in NETS.items()}
CLS = {nm: BASE[nm].argmax(1) for nm in NETS}
table7, t0 = {}, time.time()

for rate in RATES:
    stego = {}
    for cfg, (wd, wr, wg) in {"4": (1, 1, 0), "7": (1, 1, 1)}.items():
        outs = []
        for p in paths:
            c = CACHE[p]
            rho = (wd * c["D"] + wr * c["R"] + wg * c["G"]) / (wd + wr + wg)
            o = f"/tmp/tr_{cfg}_{os.path.basename(p)}"
            E.embed(p, o, rng.integers(0, 2, int(rate * c["n"])).astype(np.uint8), rho)
            outs.append(o)
        stego[cfg] = outs
    for nm, m in NETS.items():
        dp = {}
        for cfg in ("4", "7"):
            P1 = infer(m, stego[cfg])
            dp[cfg] = np.abs(P1[np.arange(len(paths)), CLS[nm]] - BASE[nm][np.arange(len(paths)), CLS[nm]])
        s, pv = wilcoxon(dp["7"], dp["4"])
        d = np.sign(dp["7"] - dp["4"])
        table7[f"{nm}@{rate}"] = dict(
            mean_7=float(dp["7"].mean()), mean_4=float(dp["4"].mean()),
            reduction=float(100 * (1 - dp["7"].mean() / dp["4"].mean())),
            p=float(pv), cliff=float((d < 0).mean() - (d > 0).mean()),
            surrogate=(nm == "resnet50"))
        v = table7[f"{nm}@{rate}"]
        print(f"  rate {rate:.2f} {nm:16s} 7={v['mean_7']:.5f} 4={v['mean_4']:.5f} "
              f"reduction {v['reduction']:+.1f}%  p={v['p']:.2e}  Cliff={v['cliff']:+.3f}", flush=True)
    for cfg in stego:
        for o in stego[cfg]: os.remove(o)
    print(f"  --- rate {rate} done [{time.time()-t0:.0f}s]\n", flush=True)

json.dump(dict(table3=table3, table7=table7), open("/content/tables37.json", "w"), indent=2)
print("=" * 78)
print("TABLE 3")
for nm, v in table3.items():
    print(f"  {nm:16s} {v['acc']:.4f}  {v['auc']:.4f}  {v['f1']:.4f}  "
          f"{v['sens'][0]:.3f}/{v['sens'][1]:.3f}/{v['sens'][2]:.3f}")
print("\nTABLE 7 — config 7 against config 4, embedded with the ResNet-50 map")
print(f"{'rate':>5} {'model':>17} {'cfg7':>9} {'cfg4':>9} {'reduction':>10} {'p':>10} {'Cliff':>7}")
for k, v in table7.items():
    nm, r = k.split("@")
    tag = " (surrogate)" if v["surrogate"] else ""
    print(f"{float(r):>5.2f} {nm:>17} {v['mean_7']:>9.5f} {v['mean_4']:>9.5f} "
          f"{v['reduction']:>+9.1f}% {v['p']:>10.2e} {v['cliff']:>+7.3f}{tag}")
print("=" * 78)
print(open("/content/tables37.json").read()[:800])

# ============================================================
#  TABLE 6 — comparison against JPEG-domain baselines
#
#  UERD [12] is re-implemented from Guo et al.; DC-only [23] is the manual
#  solution to the diagnostic problem and uses a different carrier, so it
#  carries a hard capacity ceiling. All methods embed the SAME number of
#  bits per image, sized from the AC carrier, and are evaluated on the same
#  frozen surrogate. J-UNIWARD is not included; see the note in Section 5.5.
#  ~35 min.
# ============================================================
import os, gc, json, time, warnings
import numpy as np, cv2, jpegio, torch
from scipy.stats import wilcoxon
from skimage.metrics import structural_similarity as ssim_fn
import embed_core as E
warnings.filterwarnings("ignore")

# refresh embed_core with the baseline additions
BASE_SRC = open("/content/embed_core.py").read()
if "uerd_cost" not in BASE_SRC:
    raise SystemExit("embed_core.py predates the baselines; rerun the module cell")

ROOT, QF, N_IMG = "/content/data", 75, 120
RATES = [0.05, 0.10]
rng = np.random.default_rng(42)
te = df[df.split == "test"]
sub = te.sample(min(N_IMG, len(te)), random_state=42)
paths = [f"{ROOT}/jpeg_qf{QF}/{s}.jpg" for s in sub.slice_id]

print("caching cost maps and baselines ...", flush=True)
TAB = E.rate_table(paths[:20], per_img=150)
CACHE = {}
for i, p in enumerate(paths):
    j = jpegio.read(p)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    Q = j.quant_tables[0].astype(float); del j; gc.collect()
    img8 = cv2.imread(p, cv2.IMREAD_GRAYSCALE)
    D = E.ranknorm(E.rho_D(Q, C.shape))
    R = E.ranknorm(E.rho_R(TAB, C.shape))
    G = E.ranknorm(rho_G(net, img8, Q))
    CACHE[p] = dict(D=D, R=R, G=G,
                    UERD=E.ranknorm(E.uerd_cost(C, Q)),
                    prop=(D + R + G) / 3,
                    n_ac=len(E.carrier(C)[0]), n_dc=len(E.carrier_dc(C)[0]),
                    cover=img8)
    if (i + 1) % 40 == 0: print(f"  {i+1}/{len(paths)}", flush=True)

dc_ceiling = np.median([CACHE[p]["n_dc"] / 2 / CACHE[p]["n_ac"] for p in paths])
print(f"\nDC-only capacity ceiling: {dc_ceiling:.4f} bpnzAC-equivalent (median)\n")

@torch.no_grad()
def probs(files):
    P = []
    for k in range(0, len(files), 32):
        xs = [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in files[k:k+32]]
        P.append(torch.softmax(net(torch.cat(xs)), 1).cpu().numpy())
    return np.vstack(P)

P0 = probs(paths); CLS0 = P0.argmax(1)
METHODS = ["random", "UERD", "DC-only", "distortion", "proposed"]
rows, per_img = [], {}

for rate in RATES:
    for meth in METHODS:
        outs, sizes, psnr, ssim, ok_idx, ber, fails = [], [], [], [], [], [], 0
        for i, p in enumerate(paths):
            c = CACHE[p]
            m = int(rate * c["n_ac"])
            mode = "dc" if meth == "DC-only" else "ac"
            rho = {"random": None, "UERD": c["UERD"], "DC-only": c["D"],
                   "distortion": c["D"], "proposed": c["prop"]}[meth]
            if rho is None: rho = rng.random(c["D"].shape)
            bits = rng.integers(0, 2, m).astype(np.uint8)
            o = f"/tmp/b_{os.path.basename(p)}"
            try:
                st = E.embed_mode(p, o, bits, rho, mode=mode)
            except Exception:
                fails += 1; continue
            rec = cv2.imread(o, cv2.IMREAD_GRAYSCALE).astype(np.float64)
            cov = c["cover"].astype(np.float64)
            mse = ((rec - cov) ** 2).mean()
            psnr.append(10 * np.log10(255 ** 2 / max(mse, 1e-12)))
            ssim.append(ssim_fn(c["cover"], cv2.imread(o, cv2.IMREAD_GRAYSCALE), data_range=255))
            sizes.append(st["size_pct"]); outs.append(o); ok_idx.append(i)
            if i < 5:
                ber.append(float(np.mean(bits != E.extract_mode(o, m, mode=mode))))
        if fails == len(paths):
            rows.append(dict(rate=rate, method=meth, feasible=False, fails=fails))
            print(f"  rate {rate:.2f} {meth:11s} INFEASIBLE on all {fails} images", flush=True)
            continue
        P1 = probs(outs)
        dp = np.abs(P1[np.arange(len(ok_idx)), CLS0[ok_idx]] - P0[ok_idx, CLS0[ok_idx]])
        flip = float((P1.argmax(1) != CLS0[ok_idx]).mean())
        rec = dict(rate=rate, method=meth, feasible=True, n=len(ok_idx), fails=fails,
                   mean_dp=float(dp.mean()), flip=flip, size=float(np.mean(sizes)),
                   psnr=float(np.mean(psnr)), ssim=float(np.mean(ssim)),
                   ber=float(np.mean(ber)) if ber else None)
        rows.append(rec); per_img[f"{meth}@{rate}"] = (ok_idx, dp.tolist())
        print(f"  rate {rate:.2f} {meth:11s} |dp| {dp.mean():.5f} | flip {100*flip:4.2f}% | "
              f"size {np.mean(sizes):+.2f}% | PSNR {np.mean(psnr):5.2f} | SSIM {np.mean(ssim):.5f}"
              f"{'' if not fails else f'  ({fails} failed)'}", flush=True)
        for o in outs: os.remove(o)
    print()

# paired tests: proposed against each baseline, on the shared images
tests = {}
for rate in RATES:
    a = per_img.get(f"proposed@{rate}")
    if not a: continue
    for meth in ["random", "UERD", "DC-only", "distortion"]:
        b = per_img.get(f"{meth}@{rate}")
        if not b: continue
        ia, va = a; ib, vb = b
        shared = sorted(set(ia) & set(ib))
        x = np.array([va[ia.index(i)] for i in shared])
        y = np.array([vb[ib.index(i)] for i in shared])
        s, pv = wilcoxon(x, y)
        d = np.sign(x - y)
        tests[f"{meth}@{rate}"] = dict(n=len(shared), prop=float(x.mean()),
            base=float(y.mean()), reduction=float(100 * (1 - x.mean() / y.mean())),
            p=float(pv), cliff=float((d < 0).mean() - (d > 0).mean()))

json.dump(dict(rows=rows, tests=tests, dc_ceiling=float(dc_ceiling)),
          open("/content/table6.json", "w"), indent=2)
print("=" * 84)
print(f"{'rate':>5} {'method':>11} {'mean|dp|':>10} {'flip%':>6} {'size%':>7} "
      f"{'PSNR':>7} {'SSIM':>8} {'BER':>5}")
for r in rows:
    if not r["feasible"]:
        print(f"{r['rate']:>5.2f} {r['method']:>11}   infeasible (carrier ceiling)"); continue
    print(f"{r['rate']:>5.2f} {r['method']:>11} {r['mean_dp']:>10.5f} {100*r['flip']:>6.2f} "
          f"{r['size']:>+7.2f} {r['psnr']:>7.2f} {r['ssim']:>8.5f} {r['ber']:>5.3f}")
print("\nproposed against each baseline, paired Wilcoxon on |delta p|")
for k, v in tests.items():
    meth, rate = k.split("@")
    print(f"  rate {float(rate):.2f} vs {meth:11s}: {v['prop']:.5f} vs {v['base']:.5f}  "
          f"reduction {v['reduction']:+.1f}%  p={v['p']:.2e}  Cliff={v['cliff']:+.3f}")
print(f"\nDC-only ceiling {dc_ceiling:.4f} bpnzAC-equivalent")
print("=" * 84)

