# --- corrected inference pipeline ---
def _prep512(img8):
    x = torch.from_numpy(img8.astype(np.float32) / 255.)[None, None].repeat(1, 3, 1, 1)
    return (x.to(DEV) - MEAN) / STD

def _forward(x512):
    return net(F.interpolate(x512, (224, 224), mode="bilinear",
                             align_corners=False, antialias=True))

def to_tensor(img8):
    return F.interpolate(_prep512(img8), (224, 224), mode="bilinear",
                         align_corners=False, antialias=True)

from scipy.fftpack import dct
def rho_G(net_, img8, Q):
    x = _prep512(img8).requires_grad_(True)
    out = _forward(x); cls = int(out.argmax(1))
    net_.zero_grad(); out[0, cls].backward()
    g = x.grad[0].sum(0).detach().cpu().numpy()
    nb = g.shape[0] // 8
    b = g.reshape(nb, 8, nb, 8).transpose(0, 2, 1, 3)
    G = np.abs(dct(dct(b, axis=2, norm="ortho"), axis=3, norm="ortho") * Q)
    return G.transpose(0, 2, 1, 3).reshape(g.shape)

# --- models ---
def build(arch):
    m = getattr(models, arch)(weights=None)
    if hasattr(m, "fc"): m.fc = nn.Linear(m.fc.in_features, 3)
    elif isinstance(m.classifier, nn.Sequential):
        last = [x for x in m.classifier if isinstance(x, nn.Linear)][-1]
        m.classifier[-1] = nn.Linear(last.in_features, 3)
    else: m.classifier = nn.Linear(m.classifier.in_features, 3)
    return m.to(DEV)

net = build("resnet50")
net.load_state_dict(torch.load(f"{DRIVE}/resnet50.pt", map_location=DEV))
net.eval()
for p in net.parameters(): p.requires_grad_(False)

from torch.utils.data import DataLoader
