# ============================================================
#  Append the baseline implementations to embed_core.py
#  UERD (Guo et al. 2015) and the DC-only carrier, plus embed/extract
#  variants that accept a carrier mode. Saved to Drive afterwards.
# ============================================================
BASELINES = '''

# ------------------------------------------------------------ baselines
def carrier_dc(C):
    """DC coefficients only, the manual solution to the diagnostic problem.
    Zeros are excluded so the carrier is reconstructible by the receiver."""
    C = np.array(C, dtype=np.int64, copy=True)
    r, c = np.nonzero(C)
    keep = (r % 8 == 0) & (c % 8 == 0)
    r, c = r[keep], c[keep]
    o = np.lexsort((c, r))
    return r[o], c[o]


def uerd_cost(C, Q):
    """Uniform embedding revisited distortion, Guo et al. 2015.

    Block energy is the quantisation-weighted sum of AC magnitudes; it is
    spread into the eight neighbouring blocks at a quarter weight; the cost
    of a coefficient is its quantisation step divided by that energy. The DC
    step is replaced by the mean of the two lowest AC steps, as in the
    original formulation.
    """
    C = np.array(C, dtype=np.int64, copy=True)
    H, W = C.shape
    nbr, nbc = H // 8, W // 8
    blocks = np.abs(C).reshape(nbr, 8, nbc, 8).transpose(0, 2, 1, 3).astype(np.float64)
    qw = Q.astype(np.float64).copy()
    energy = (blocks * qw[None, None]).sum(axis=(2, 3))
    energy -= blocks[:, :, 0, 0] * qw[0, 0]

    pad = np.pad(energy, 1, mode="edge")
    spread = energy.copy()
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            if dy or dx:
                spread += 0.25 * pad[1 + dy:1 + dy + nbr, 1 + dx:1 + dx + nbc]
    spread = np.maximum(spread, 1e-9)

    qd = qw.copy()
    qd[0, 0] = 0.5 * (qw[0, 1] + qw[1, 0])
    rho = qd[None, None] / spread[:, :, None, None]
    return rho.transpose(0, 2, 1, 3).reshape(H, W)


def embed_mode(jpg_in, jpg_out, bits, rho, mode="ac", h=7, seed=42):
    """As embed(), with a selectable carrier: all non-zero AC, or DC only."""
    j = jpegio.read(jpg_in)
    C = j.coef_arrays[0]
    Cc = np.array(C, dtype=np.int64, copy=True)
    rows, cols = (carrier(Cc) if mode == "ac" else carrier_dc(Cc))
    n, m = len(rows), len(bits)
    if m == 0 or n < 2 * m:
        raise ValueError(f"carrier too small for this payload: n={n}, m={m}")
    nu = (n // m) * m
    rows, cols = rows[:nu], cols[:nu]
    x = (np.abs(Cc[rows, cols]) % 2).astype(np.uint8)
    cost = np.maximum(rho[rows, cols].astype(np.float64), 1e-9)
    y = stc_embed(x, cost, bits, h, seed)
    flip = np.nonzero(x != y)[0]
    for i in flip:
        r, c = int(rows[i]), int(cols[i])
        C[r, c] = int(Cc[r, c]) + _dirn(int(Cc[r, c]))
    jpegio.write(j, jpg_out)
    s0, s1 = os.path.getsize(jpg_in), os.path.getsize(jpg_out)
    return dict(n=nu, m=m, changes=len(flip), size_pct=100 * (s1 - s0) / s0)


def extract_mode(jpg, m, mode="ac", h=7, seed=42):
    j = jpegio.read(jpg)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    del j; gc.collect()
    rows, cols = (carrier(C) if mode == "ac" else carrier_dc(C))
    nu = (len(rows) // m) * m
    y = (np.abs(C[rows[:nu], cols[:nu]]) % 2).astype(np.uint8)
    return stc_extract(y, m, h, seed)
'''

