# ---- control: is the concentration explained by centre bias alone? ------
import numpy as np, cv2, jpegio, gc, json
ROOT, NB = "/content/data", 64
te = df[df.split == "test"].sample(50, random_state=42)
yy, xx = np.mgrid[0:NB, 0:NB]
radial = 1.0 / (1.0 + np.hypot(yy - NB/2 + .5, xx - NB/2 + .5))   # centre-only null

real, null, frac = [], [], []
for _, r in te.iterrows():
    jp, mp = f"{ROOT}/jpeg_qf75/{r.slice_id}.jpg", f"{ROOT}/masks/{r.slice_id}.png"
    j = jpegio.read(jp); Q = j.quant_tables[0].astype(float); del j; gc.collect()
    G = rho_G(net, cv2.imread(jp, cv2.IMREAD_GRAYSCALE), Q)
    gb = G.reshape(NB, 8, NB, 8).sum(axis=(1, 3))
    m = cv2.imread(mp, cv2.IMREAD_GRAYSCALE) > 127
    tum = m.reshape(NB, 8, NB, 8).transpose(0, 2, 1, 3).reshape(NB, NB, 64).any(2)
    if tum.sum() == 0: continue
    f = tum.mean(); frac.append(f)
    real.append(gb[tum].sum() / gb.sum())
    null.append(radial[tum].sum() / radial.sum())

real, null, frac = map(np.array, (real, null, frac))
cr_real = real.mean() / frac.mean()
cr_null = null.mean() / frac.mean()
from scipy.stats import wilcoxon
s, p = wilcoxon(real, null)
print("=" * 62)
print(f"diagnostic map  concentration = {cr_real:.2f}x")
print(f"radial null     concentration = {cr_null:.2f}x")
print(f"excess over the centre-bias null = {cr_real - cr_null:+.2f}x")
print(f"paired Wilcoxon, real vs null: p = {p:.2e}")
print(f"map exceeds the null on {100*(real > null).mean():.0f}% of images")
print("=" * 62)
json.dump(dict(real=cr_real, null=cr_null, p=float(p),
               win=float((real > null).mean())),
          open("/content/centre_control.json", "w"), indent=2)

# ============================================================
#  Figure 2, corrected
#
#  Two problems in the first version. UERD cost is q divided by block
#  energy, so background blocks with near-zero energy produce enormous
#  values that swallow the colour range; we clip to percentiles computed
#  over tissue blocks only. And the rate map has no spatial variation by
#  construction: it is a per-frequency table tiled across every block, so
#  block-pooling returns a constant. Showing it as a spatial panel was
#  misleading, and it is shown in the frequency domain instead.
# ============================================================
import os, gc, warnings
import numpy as np, cv2, jpegio
import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt
import embed_core as E
warnings.filterwarnings("ignore")

plt.rcParams.update({"font.family": "serif", "font.size": 8, "figure.dpi": 300,
                     "savefig.bbox": "tight", "savefig.pad_inches": 0.02})
OUT = "/content/figs"; os.makedirs(OUT, exist_ok=True)
NB, GREEN = 64, "#00c853"

sid = df[(df.split == "test") & (df.label == 2)].slice_id.iloc[0]
jpg = f"/content/data/jpeg_qf75/{sid}.jpg"
j = jpegio.read(jpg)
C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
Q = j.quant_tables[0].astype(float); del j; gc.collect()
img = cv2.imread(jpg, cv2.IMREAD_GRAYSCALE)
mask = cv2.imread(f"/content/data/masks/{sid}.png", cv2.IMREAD_GRAYSCALE) > 127

def pool(a):
    return a.reshape(NB, 8, NB, 8).sum(axis=(1, 3))

tissue = pool((img > 12).astype(float)) > 8          # blocks carrying anatomy
tum = mask.reshape(NB, 8, NB, 8).transpose(0, 2, 1, 3).reshape(NB, NB, 64).any(2)

def show(ax, m, title, cmap="magma"):
    """Percentile clipping over tissue blocks, so a handful of extreme
    background values cannot dominate the scale."""
    lo, hi = np.percentile(m[tissue], [2, 98])
    ax.imshow(np.clip(m, lo, hi), cmap=cmap, interpolation="nearest",
              vmin=lo, vmax=hi)
    ax.contour(tum.astype(np.uint8), levels=[0.5], colors=GREEN, linewidths=0.8)
    ax.set_title(title, fontsize=7.5)
    ax.set_xticks([]); ax.set_yticks([])

fig = plt.figure(figsize=(7.2, 2.2))
gs = fig.add_gridspec(1, 4, width_ratios=[1, 1, 1, 0.85], wspace=0.12)

ax = fig.add_subplot(gs[0])
ax.imshow(img, cmap="gray")
ax.contour(mask.astype(np.uint8), levels=[0.5], colors=GREEN, linewidths=0.8)
ax.set_title("(a) cover, glioma", fontsize=7.5)
ax.set_xticks([]); ax.set_yticks([])

show(fig.add_subplot(gs[1]), np.log10(pool(E.uerd_cost(C, Q)) + 1e-12),
     "(b) distortion, UERD (5)")
show(fig.add_subplot(gs[2]), np.log10(pool(rho_G(net, img, Q)) + 1e-12),
     "(c) diagnostic (9)")

# rate cost belongs in the frequency domain, not the spatial one
TAB = E.rate_table([jpg], per_img=600)
ax = fig.add_subplot(gs[3])
im = ax.imshow(TAB, cmap="coolwarm", vmin=-abs(TAB).max(), vmax=abs(TAB).max())
ax.set_title("(d) rate (6), per frequency", fontsize=7.5)
ax.set_xlabel("horizontal frequency", fontsize=6.5)
ax.set_ylabel("vertical frequency", fontsize=6.5)
ax.set_xticks([0, 7]); ax.set_yticks([0, 7])
ax.tick_params(labelsize=6)
cb = fig.colorbar(im, ax=ax, fraction=0.046, pad=0.03)
cb.set_label("bytes per unit change", fontsize=6)
cb.ax.tick_params(labelsize=5.5)

fig.savefig(f"{OUT}/figure2_maps.pdf")
fig.savefig(f"{OUT}/figure2_maps.png")
plt.close(fig)

print(f"tissue blocks: {tissue.sum()} of {NB*NB}")
print(f"UERD over tissue: {np.percentile(pool(E.uerd_cost(C,Q))[tissue],[2,50,98])}")
print(f"rate table: {TAB.min():+.2f} to {TAB.max():+.2f} bytes, "
      f"spatial variance {pool(E.rho_R(TAB, C.shape)).std():.3e} (zero by construction)")
import subprocess
subprocess.run(["cp", "-r", OUT, "/content/drive/MyDrive/dhide_ckpt/"], check=False)
print("figure 2 rewritten and copied to Drive")

