# ---- rebuild the evaluation set and the cost-map cache ------------------
import os, gc, time, warnings
import numpy as np, cv2, jpegio, torch
import embed_core as E
warnings.filterwarnings("ignore")

ROOT, QF, N_IMG = "/content/data", 75, 120
te = df[df.split == "test"]
sub = te.sample(min(N_IMG, len(te)), random_state=42)     # same seed as Table 6
paths = [f"{ROOT}/jpeg_qf{QF}/{s}.jpg" for s in sub.slice_id]

print("rate table ...", flush=True)
t0 = time.time()
TAB = E.rate_table(paths[:20], per_img=150)

print("cost maps ...", flush=True)
CACHE = {}
for i, p in enumerate(paths):
    j = jpegio.read(p)
    C = np.array(j.coef_arrays[0], dtype=np.int64, copy=True)
    Q = j.quant_tables[0].astype(float); del j; gc.collect()
    img8 = cv2.imread(p, cv2.IMREAD_GRAYSCALE)
    D = E.ranknorm(E.rho_D(Q, C.shape))
    R = E.ranknorm(E.rho_R(TAB, C.shape))
    G = E.ranknorm(rho_G(net, img8, Q))
    CACHE[p] = dict(D=D, R=R, G=G, UERD=E.ranknorm(E.uerd_cost(C, Q)),
                    prop=(D + R + G) / 3, cover=img8,
                    n_ac=len(E.carrier(C)[0]), n_dc=len(E.carrier_dc(C)[0]))
    if (i + 1) % 30 == 0:
        print(f"  {i+1}/{len(paths)}  [{time.time()-t0:.0f}s]", flush=True)

@torch.no_grad()
def probs(files):
    P = []
    for k in range(0, len(files), 32):
        xs = [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in files[k:k+32]]
        P.append(torch.softmax(net(torch.cat(xs)), 1).cpu().numpy())
    return np.vstack(P)

P0 = probs(paths); CLS0 = P0.argmax(1)
labels = np.asarray(sub.label.values) - 1
from sklearn.metrics import roc_auc_score
print(f"\nclean cover on these {len(paths)} images: "
      f"accuracy {(CLS0 == labels).mean():.4f}, "
      f"AUC {roc_auc_score(labels, P0, multi_class='ovr', average='macro', labels=[0,1,2]):.4f}")
print("expected 0.9083 / 0.9858 — a match confirms the same evaluation set")
print("\nready. rerun the Table 8 cell.")

# ============================================================
#  TABLE 8 rerun — transfer under the current definition
#
#  The earlier run compared (D+R+G) against (D+R) with the non-adaptive
#  distortion term. Section 6.4 replaced that term with UERD, so this
#  repeats the transfer test as UERD+G against UERD, matching the method
#  the paper actually recommends. Five payload seeds, as in Table 7.
#  ~25 min on CPU.
# ============================================================
import os, json, time, warnings
import numpy as np, torch, cv2, torch.nn as nn
from torchvision import models
from scipy.stats import wilcoxon
import embed_core as E
warnings.filterwarnings("ignore")

DRIVE = "/content/drive/MyDrive/dhide_ckpt"
SEEDS, RATES = [42, 123, 456, 789, 1011], [0.05, 0.10]

def build(arch):
    m = getattr(models, arch)(weights=None)
    if hasattr(m, "fc"): m.fc = nn.Linear(m.fc.in_features, 3)
    elif isinstance(m.classifier, nn.Sequential):
        last = [x for x in m.classifier if isinstance(x, nn.Linear)][-1]
        m.classifier[-1] = nn.Linear(last.in_features, 3)
    else: m.classifier = nn.Linear(m.classifier.in_features, 3)
    return m.to(DEV)

NETS = {"resnet50": net}
for arch in ["efficientnet_b0", "densenet121"]:
    m = build(arch)
    m.load_state_dict(torch.load(f"{DRIVE}/{arch}.pt", map_location=DEV))
    m.eval()
    for p_ in m.parameters(): p_.requires_grad_(False)
    NETS[arch] = m
print("models loaded:", list(NETS))

@torch.no_grad()
def probs_of(model, files):
    P = []
    for k in range(0, len(files), 32):
        xs = [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in files[k:k+32]]
        P.append(torch.softmax(model(torch.cat(xs)), 1).cpu().numpy())
    return np.vstack(P)

BASE = {nm: probs_of(m, paths) for nm, m in NETS.items()}
CLS = {nm: BASE[nm].argmax(1) for nm in NETS}
idx = np.arange(len(paths))
for nm in NETS:
    print(f"  {nm:16s} clean accuracy on these images: "
          f"{(CLS[nm] == np.asarray(sub.label.values) - 1).mean():.4f}")

acc, t0 = {}, time.time()
for rate in RATES:
    for seed in SEEDS:
        stego = {}
        for cfg, mk in {"UERD": lambda c: c["UERD"],
                        "UERD+G": lambda c: (c["UERD"] + c["G"]) / 2}.items():
            rng = np.random.default_rng(seed)          # identical payloads
            outs = []
            for p in paths:
                c = CACHE[p]
                o = f"/tmp/t8_{cfg}_{os.path.basename(p)}"
                E.embed_mode(p, o, rng.integers(0, 2, int(rate * c["n_ac"])).astype(np.uint8),
                             mk(c), mode="ac")
                outs.append(o)
            stego[cfg] = outs
        for nm, m in NETS.items():
            dp = {}
            for cfg in ("UERD", "UERD+G"):
                P1 = probs_of(m, stego[cfg])
                dp[cfg] = np.abs(P1[idx, CLS[nm]] - BASE[nm][idx, CLS[nm]])
            acc.setdefault(f"{nm}@{rate}", {"a": [], "b": []})
            acc[f"{nm}@{rate}"]["a"] += dp["UERD+G"].tolist()
            acc[f"{nm}@{rate}"]["b"] += dp["UERD"].tolist()
        for cfg in stego:
            for o in stego[cfg]: os.remove(o)
        print(f"  rate {rate:.2f} seed {seed:5d} done  [{time.time()-t0:.0f}s]", flush=True)

res, pv_all = {}, []
for k, v in acc.items():
    a, b = np.array(v["a"]), np.array(v["b"])
    s, pv = wilcoxon(a, b); d = np.sign(a - b)
    res[k] = dict(n=len(a), prop=float(a.mean()), uerd=float(b.mean()),
                  reduction=float(100 * (1 - a.mean() / b.mean())),
                  p=float(pv), cliff=float((d < 0).mean() - (d > 0).mean()),
                  win=float((a < b).mean()))
    pv_all.append((k, pv))
order = sorted(pv_all, key=lambda x: x[1])
for i, (k, pv) in enumerate(order):
    res[k]["holm"] = float(min(pv * (len(order) - i), 1.0))

