import numpy as np, cv2, jpegio, torch
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.model_selection import StratifiedKFold, cross_val_predict
from sklearn.metrics import accuracy_score
import sys; sys.path.insert(0, "/content")
import dctr, embed_core as E
warnings.filterwarnings("ignore")

N_IMG, RATES = 80, [0.05, 0.10]
sel_paths = paths[:N_IMG]
rng = np.random.default_rng(42)
METHODS = {"random": None, "UERD": "UERD", "distortion": "D", "proposed": "prop"}

print(f"extracting cover features for {len(sel_paths)} images ...", flush=True)
t0 = time.time()
COVER = np.array([dctr.dctr(cv2.imread(p, cv2.IMREAD_GRAYSCALE)) for p in sel_paths])
print(f"  done [{time.time()-t0:.0f}s]", flush=True)

def pe(Xs):
    """Detection error of a linear detector, cover against stego."""
    X = np.vstack([COVER, Xs])
    y = np.r_[np.zeros(len(COVER)), np.ones(len(Xs))]
    grp = np.r_[np.arange(len(COVER)), np.arange(len(Xs))]   # keep pairs together
    clf = make_pipeline(StandardScaler(), LogisticRegression(C=0.01, max_iter=3000))
    cv = StratifiedKFold(5, shuffle=True, random_state=42)
    pred = cross_val_predict(clf, X, y, cv=cv)
    acc = accuracy_score(y, pred)
    return float(acc), float(1 - acc)

res = {}
for rate in RATES:
    for name, key in METHODS.items():
        feats = []
        for p in sel_paths:
            c = CACHE[p]
            rho = rng.random(c["D"].shape) if key is None else (
                (c["UERD"] + c["G"]) / 2 if key == "prop" else c[key])
            o = f"/tmp/d_{os.path.basename(p)}"
            E.embed_mode(p, o, rng.integers(0, 2, int(rate * c["n_ac"])).astype(np.uint8),
                         rho, mode="ac")
            feats.append(dctr.dctr(cv2.imread(o, cv2.IMREAD_GRAYSCALE)))
            os.remove(o)
        acc, err = pe(np.array(feats))
        res[f"{name}@{rate}"] = dict(acc=acc, pe=err)
        print(f"  rate {rate:.2f} {name:11s} detection accuracy {acc:.3f}  "
              f"P_E {err:.3f}  [{time.time()-t0:.0f}s]", flush=True)
    print()

json.dump(res, open("/content/table9_dctr.json", "w"), indent=2)
print("=" * 62)
print(f"{'rate':>5} {'criterion':>12} {'detection acc':>14} {'P_E':>8}")
for k in sorted(res, key=lambda x: (float(x.split('@')[1]), x)):
    nm, r = k.split("@")
    print(f"{float(r):>5.2f} {nm:>12} {res[k]['acc']:>14.3f} {res[k]['pe']:>8.3f}")
print("\nP_E of 0.5 means undetectable; lower means more detectable.")
print("=" * 62)
