# ---- corrected evaluation: cover and its stego must share a fold --------
import numpy as np, os, cv2, json, time
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.model_selection import StratifiedGroupKFold, cross_val_predict
from sklearn.metrics import accuracy_score
import dctr, embed_core as E

rng = np.random.default_rng(42)
METHODS = {"random": None, "UERD": "UERD", "distortion": "D", "proposed": "prop"}

def pe_grouped(Xs):
    """Detection error with cover/stego pairs kept in the same fold.

    Without grouping the classifier sees an image's cover in training and
    its stego in test; the two are near-identical, so it predicts the stego
    as cover and accuracy falls below chance. That is an artefact of the
    split, not a property of the embedding.
    """
    X = np.vstack([COVER, Xs])
    y = np.r_[np.zeros(len(COVER)), np.ones(len(Xs))]
    grp = np.r_[np.arange(len(COVER)), np.arange(len(Xs))]
    clf = make_pipeline(StandardScaler(), LogisticRegression(C=0.01, max_iter=3000))
    cv = StratifiedGroupKFold(5, shuffle=True, random_state=42)
    pred = cross_val_predict(clf, X, y, cv=cv, groups=grp)
    acc = accuracy_score(y, pred)
    return float(acc), float(1 - acc)

res, t0 = {}, time.time()
for rate in [0.05, 0.10]:
    for name, key in METHODS.items():
        feats = []
        for p in sel_paths:
            c = CACHE[p]
            rho = rng.random(c["D"].shape) if key is None else (
                (c["UERD"] + c["G"]) / 2 if key == "prop" else c[key])
            o = f"/tmp/d_{os.path.basename(p)}"
            E.embed_mode(p, o, rng.integers(0, 2, int(rate * c["n_ac"])).astype(np.uint8),
                         rho, mode="ac")
            feats.append(dctr.dctr(cv2.imread(o, cv2.IMREAD_GRAYSCALE)))
            os.remove(o)
        acc, err = pe_grouped(np.array(feats))
        res[f"{name}@{rate}"] = dict(acc=acc, pe=err)
        print(f"  rate {rate:.2f} {name:11s} accuracy {acc:.3f}  P_E {err:.3f}  "
              f"[{time.time()-t0:.0f}s]", flush=True)
    print()

json.dump(res, open("/content/table9_dctr_fixed.json", "w"), indent=2)
print("=" * 64)
print(f"{'rate':>5} {'criterion':>12} {'accuracy':>10} {'P_E':>8}")
for k in sorted(res, key=lambda x: (float(x.split('@')[1]), -res[x]['pe'])):
    nm, r = k.split("@")
    print(f"{float(r):>5.2f} {nm:>12} {res[k]['acc']:>10.3f} {res[k]['pe']:>8.3f}")
print("\nP_E = 0.5 is undetectable; below 0.5 means the detector wins.")
print("Any accuracy below 0.5 now would indicate a remaining problem.")
print("=" * 64)

