# ============================================================
#  TABLE 11 / FIGURE 7 — the diagnostic-security frontier
#  Sweeping the diagnostic weight from 0 (pure UERD) to 1 (pure
#  diagnostic) traces the exchange the title claims. Each point is
#  measured on both axes: disturbance to the frozen classifier and
#  detection error under DCTR. ~25 min.
# ============================================================
import os, json, time, warnings
import numpy as np, cv2, torch
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.model_selection import StratifiedGroupKFold, cross_val_predict
from sklearn.metrics import accuracy_score
import dctr, embed_core as E
warnings.filterwarnings("ignore")

WEIGHTS = [0.0, 0.25, 0.50, 0.75, 1.0]
RATES = [0.05, 0.10]
rng = np.random.default_rng(42)

@torch.no_grad()
def probs_local(files):
    P = []
    for k in range(0, len(files), 32):
        xs = [to_tensor(cv2.imread(f, cv2.IMREAD_GRAYSCALE)) for f in files[k:k+32]]
        P.append(torch.softmax(net(torch.cat(xs)), 1).cpu().numpy())
    return np.vstack(P)

B0 = probs_local(sel_paths); C0 = B0.argmax(1); ii = np.arange(len(sel_paths))

def detect_error(Xs):
    X = np.vstack([COVER, Xs])
    y = np.r_[np.zeros(len(COVER)), np.ones(len(Xs))]
    g = np.r_[np.arange(len(COVER)), np.arange(len(Xs))]
    clf = make_pipeline(StandardScaler(), LogisticRegression(C=0.01, max_iter=3000))
    cv = StratifiedGroupKFold(5, shuffle=True, random_state=42)
    return float(1 - accuracy_score(y, cross_val_predict(clf, X, y, cv=cv, groups=g)))

front, t0 = {}, time.time()
for rate in RATES:
    for w in WEIGHTS:
        outs, feats = [], []
        for p in sel_paths:
            c = CACHE[p]
            rho = (1 - w) * c["UERD"] + w * c["G"]
            o = f"/tmp/f_{os.path.basename(p)}"
            E.embed_mode(p, o, rng.integers(0, 2, int(rate * c["n_ac"])).astype(np.uint8),
                         rho, mode="ac")
            outs.append(o)
            feats.append(dctr.dctr(cv2.imread(o, cv2.IMREAD_GRAYSCALE)))
        P1 = probs_local(outs)
        dp = np.abs(P1[ii, C0] - B0[ii, C0])
        pe = detect_error(np.array(feats))
        front[f"{rate}|{w}"] = dict(w=w, rate=rate, dp=float(dp.mean()),
                                    dp_med=float(np.median(dp)), pe=pe)
        print(f"  rate {rate:.2f}  w_G {w:.2f}  |dp| {dp.mean():.5f}  P_E {pe:.3f}  "
              f"[{time.time()-t0:.0f}s]", flush=True)
        for o in outs: os.remove(o)
    print()

# knee: largest diagnostic gain per unit of detection error surrendered
print("=" * 70)
print(f"{'rate':>5} {'w_G':>5} {'mean|dp|':>10} {'P_E':>7} {'dp gain':>9} "
      f"{'P_E cost':>9} {'ratio':>7}")
for rate in RATES:
    b = front[f"{rate}|0.0"]
    for w in WEIGHTS:
        v = front[f"{rate}|{w}"]
        gain = 100 * (1 - v["dp"] / b["dp"])
        cost = 100 * (1 - v["pe"] / b["pe"])
        r = gain / cost if cost > 1e-9 else float("nan")
        print(f"{rate:>5.2f} {w:>5.2f} {v['dp']:>10.5f} {v['pe']:>7.3f} "
              f"{gain:>+8.1f}% {cost:>+8.1f}% {r:>7.2f}")
    print()
print("ratio > 1 means diagnostic gain outpaces the security given up.")
print("=" * 70)
json.dump(front, open("/content/frontier.json", "w"), indent=2)
print(open("/content/frontier.json").read())

