COVER = np.array([dctr.dctr(cv2.imread(p, cv2.IMREAD_GRAYSCALE)) for p in sel])
print(f"cover DCTR features {COVER.shape}\n", flush=True)

from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler
from sklearn.pipeline import make_pipeline
from sklearn.model_selection import StratifiedGroupKFold, cross_val_predict
from sklearn.metrics import accuracy_score

def detect_error(X1):
    X = np.vstack([COVER, X1])
    y = np.r_[np.zeros(len(COVER)), np.ones(len(X1))]
    g = np.r_[np.arange(len(COVER)), np.arange(len(X1))]
    clf = make_pipeline(StandardScaler(), LogisticRegression(C=0.01, max_iter=3000))
    cv = StratifiedGroupKFold(5, shuffle=True, random_state=42)
    return float(1 - accuracy_score(y, cross_val_predict(clf, X, y, cv=cv, groups=g)))

raw = {a: {str(r): [] for r in RATES} for a in ARMS}
pe = {a: {} for a in ARMS}
t0 = time.time()

for rate in RATES:
    for arm, mk in ARMS.items():
        feats = []
        for seed in SEEDS:
            rng = np.random.default_rng(seed)
            outs = []
            for p in paths:
                c = CACHE[p]
                o = f"/tmp/jw_{os.path.basename(p)}"
                E.embed_mode(p, o, rng.integers(0, 2, int(rate * c["n_ac"])).astype(np.uint8),
                             mk(c), mode="ac")
                outs.append(o)
            P1 = probs(outs)
            raw[arm][str(rate)].append(np.abs(P1[ii, CLS] - BASE[ii, CLS]).tolist())
            if seed == SEEDS[0]:
                feats = [dctr.dctr(cv2.imread(o, cv2.IMREAD_GRAYSCALE)) for o in outs[:80]]
            for o in outs: os.remove(o)
        pe[arm][str(rate)] = detect_error(np.array(feats))
        m = np.array(raw[arm][str(rate)]).mean(axis=0)
        print(f"  rate {rate:.2f} {arm:12s} |dp| {m.mean():.5f}  P_E {pe[arm][str(rate)]:.3f} "
              f"[{time.time()-t0:.0f}s]", flush=True)
    print()

json.dump(dict(seeds=SEEDS, rates=RATES, arms=list(ARMS), raw=raw, pe=pe),
          open("/content/juniward_results.json", "w"))
subprocess.run(["cp", "/content/juniward_results.json", f"{DRIVE}/"], check=False)

def im(arm, rate): return np.array(raw[arm][str(rate)]).mean(axis=0)

print("=" * 92)
print("FOUR-WAY COMPARISON, image-level, n = %d" % len(paths))
print(f"{'rate':>5} {'criterion':>13} {'mean e-4':>9} {'median e-5':>11} {'P_E':>7} "
      f"{'vs base':>9} {'p':>10} {'Cliff':>7}")
out = {}
for rate in RATES:
    for base_arm, add_arm in (("UERD", "UERD+0.25G"), ("J-UNIWARD", "JUNI+0.25G")):
        b = im(base_arm, rate); a = im(add_arm, rate)
        s, pv = wilcoxon(a, b); d = np.sign(a - b)
        for nm, v, extra in ((base_arm, b, None), (add_arm, a, (pv, d))):
            red = "" if extra is None else f"{100*(1-a.mean()/b.mean()):+8.1f}%"
            pp = "" if extra is None else f"{pv:10.2e}"
            cf = "" if extra is None else f"{float((d<0).mean()-(d>0).mean()):+7.3f}"
            print(f"{rate:>5.2f} {nm:>13} {v.mean()*1e4:>9.3f} {np.median(v)*1e5:>11.3f} "
                  f"{pe[nm][str(rate)]:>7.3f} {red:>9} {pp:>10} {cf:>7}")
        out[f"{add_arm}@{rate}"] = dict(base=float(b.mean()), prop=float(a.mean()),
            red=float(100*(1-a.mean()/b.mean())), p=float(pv),
            cliff=float((d<0).mean()-(d>0).mean()), win=float((a<b).mean()))
print("\nJ-UNIWARD against UERD, no diagnostic term")
for rate in RATES:
    x = im("J-UNIWARD", rate); y = im("UERD", rate)
    s, pv = wilcoxon(x, y); d = np.sign(x - y)
    print(f"  rate {rate:.2f}: J-UNIWARD {x.mean()*1e4:.3f} vs UERD {y.mean()*1e4:.3f} e-4  "
          f"({100*(1-x.mean()/y.mean()):+.1f}%)  p={pv:.3f}  Cliff={float((d<0).mean()-(d>0).mean()):+.3f}")
print("=" * 92)
json.dump(dict(tests=out, pe=pe, checks=chk),
          open("/content/juniward_tables.json", "w"), indent=2)
subprocess.run(["cp", "/content/juniward_tables.json", f"{DRIVE}/"], check=False)
print("\nsaved to Drive.")

"""
Paired payload-sweep design for:
  "Choosing an AEAD for hidden channels using game theory"

Replaces the per-configuration comparison, which had no statistical power.

Design
------
Every payload is embedded into the SAME images. Detector scores are therefore
paired within image, so the dominant nuisance term -- image content -- cancels
in the comparison. Two consequences:

  * Sensitivity. A Wilcoxon signed-rank test on within-image score differences
    resolves effects an unpaired comparison of P_E cannot see at the same n.
  * Cost. Detectability is estimated as a curve over payload, and each AEAD
    configuration is read off that curve, rather than requiring its own
    independent experiment.

Feature extraction fixes that this module depends on
----------------------------------------------------
  * sealwatch.dctr.extract expects pixels in [-128, 127], so 128 is subtracted.
  * Its q argument is the quantisation STEP, not the JPEG quality factor.

Sanity gate
-----------
run_sanity_check() must pass before any measurement is trusted. It embeds at a
rate that is unambiguously detectable and refuses to continue if the detector
does not see it. Both bugs found in the previous harness would have been caught
here in minutes.
"""

from __future__ import annotations

import os
import json
import time
import warnings
from dataclasses import dataclass, asdict

import numpy as np
from PIL import Image
from scipy import stats

import jpeglib
import conseal as cl
import sealwatch as sw
from sealwatch.ensemble_classifier import FldEnsembleTrainer

warnings.filterwarnings("ignore", message=".*converg.*")


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

COVER_DIR = "/content/cov"
WORK_DIR = "/content/work"
OUT_DIR = "/content/drive/MyDrive/aead_stego/res"

COVER_SIZE = 256          # square side after resize
QF = 75                   # JPEG quality factor of the cover
Q_STEP = 4                # DCTR quantisation step (calibrated, not the QF)
TEST_FRAC = 0.40


@dataclass(frozen=True)
class AeadConfig:
    """An AEAD choice, expressed as the covert payload it costs."""
    name: str
    msg_bytes: int
    tag_bytes: int
    nonce_bytes: int = 0

    @property
    def total_bytes(self) -> int:
        return self.msg_bytes + self.tag_bytes + self.nonce_bytes

    @property
    def forgery_bits(self) -> int:
        """Work factor of a forgery attempt, in bits."""
        return self.tag_bytes * 8


def aead_configs(msg_bytes: int = 16) -> list[AeadConfig]:
    m = msg_bytes
    return [
        AeadConfig("Ascon-AEAD128",      m, 16),
        AeadConfig("Ascon-AEAD128-t96",  m, 12),
        AeadConfig("Ascon-AEAD128-t64",  m, 8),
        AeadConfig("Xoodyak",            m, 16),
        AeadConfig("GIFT-COFB",          m, 16),
        AeadConfig("TinyJAMBU",          m, 8),
    ]


# ---------------------------------------------------------------------------
# Cover preparation, embedding, features
# ---------------------------------------------------------------------------

def prepare_cover(src: str, dst: str, size: int | None = None,
                  qf: int | None = None) -> None:
    # Resolved at call time: module-level COVER_SIZE / QF are meant to be
    # reassignable after import, which a default argument would freeze.
    size = COVER_SIZE if size is None else size
    qf = QF if qf is None else qf
    im = Image.open(src).convert("L")
    w, h = im.size
    s = min(w, h)
    im = im.crop(((w - s) // 2, (h - s) // 2, (w + s) // 2, (h + s) // 2))
    im.resize((size, size), Image.LANCZOS).save(dst, quality=qf, subsampling=0)


def nzac(y: np.ndarray) -> int:
    return int((y != 0).sum() - (y[:, :, 0, 0] != 0).sum())


def embed(cover: str, stego: str, alpha: float, embedder: str, seed: int) -> int:
    """conseal returns the stego coefficients, not a difference."""
    j = jpeglib.read_dct(cover)
    y0 = j.Y.copy()
    if embedder == "juniward":
        sp = jpeglib.read_spatial(cover)
        y1 = cl.juniward.simulate_single_channel(
            x0=sp.spatial[..., 0], y0=y0, qt=j.qt[0], alpha=alpha, seed=seed)
    elif embedder == "uerd":
        y1 = cl.uerd.simulate_single_channel(
            y0=y0, qt=j.qt[0], alpha=alpha, seed=seed)
    else:
        raise ValueError(embedder)
    j.Y = y1
    j.write_dct(stego)
    return int((y1 != y0).sum())


def features(path: str, q_step: int | None = None) -> np.ndarray:
    q_step = Q_STEP if q_step is None else q_step
    x = jpeglib.read_spatial(path).spatial[..., 0].astype(float) - 128.0
    d = sw.dctr.extract(x, q=q_step)
    return np.concatenate([np.ravel(v) for v in d.values()])


# ---------------------------------------------------------------------------
# Detector
# ---------------------------------------------------------------------------

def train_detector(Xc: np.ndarray, Xs: np.ndarray, seed: int = 0):
    trainer = FldEnsembleTrainer(Xc=Xc, Xs=Xs, seed=seed, verbose=0)
    clf, _ = trainer.train()
    return clf


def p_e_from_scores(sc: np.ndarray, ss: np.ndarray) -> dict:
    """P_E = min over thresholds of 0.5*(P_FA + P_MD)."""
    best = (0.5, 0.5, 0.5)
    for thr in np.unique(np.concatenate([sc, ss])):
        fa = float(np.mean(sc > thr))
        md = float(np.mean(ss <= thr))
        if 0.5 * (fa + md) < best[0]:
            best = (0.5 * (fa + md), fa, md)
    return {"P_E": best[0], "P_FA": best[1], "P_MD": best[2]}


# ---------------------------------------------------------------------------
# Sanity gate
# ---------------------------------------------------------------------------

def run_sanity_check(paths: list[str], alpha: float = 0.40,
                     threshold: float = 0.30, embedder: str = "juniward",
                     verbose: bool = True) -> dict:
    """Embed at a rate that must be detectable, and verify the detector sees it.

    A measurement pipeline that cannot detect alpha=0.4 is broken, whatever it
    reports at low rates.
    """
    os.makedirs(WORK_DIR, exist_ok=True)
    Xc, Xs, changes = [], [], []
    for i, p in enumerate(paths):
        c = os.path.join(WORK_DIR, "san_c.jpg")
        s = os.path.join(WORK_DIR, "san_s.jpg")
        prepare_cover(p, c)
        changes.append(embed(c, s, alpha, embedder, seed=i))
        Xc.append(features(c))
        Xs.append(features(s))
    Xc, Xs = np.array(Xc), np.array(Xs)

    n = len(Xc)
    rng = np.random.default_rng(0)
    perm = rng.permutation(n)
    n_te = max(8, int(round(TEST_FRAC * n)))
    te, tr = perm[:n_te], perm[n_te:]
    clf = train_detector(Xc[tr], Xs[tr], seed=0)
    res = p_e_from_scores(np.ravel(clf.predict_confidence(Xc[te])),
                          np.ravel(clf.predict_confidence(Xs[te])))
    res["alpha"] = alpha
    res["mean_changes"] = float(np.mean(changes))
    res["passed"] = bool(res["P_E"] < threshold)
    if verbose:
        print(f"sanity: alpha={alpha} changes={res['mean_changes']:.0f} "
              f"P_E={res['P_E']:.4f} -> {'PASS' if res['passed'] else 'FAIL'}")
    return res


# ---------------------------------------------------------------------------
# Paired sweep
# ---------------------------------------------------------------------------

def run_sweep(paths: list[str], payload_bytes: list[int],
              embedder: str = "juniward", seed: int = 0,
              verbose: bool = True) -> dict:
    """Embed every payload into every image and score them with one detector
    per payload, always on the same held-out images.

    Returns per-payload P_E plus the full matrix of per-image scores, which is
    what the paired tests consume.
    """
    os.makedirs(WORK_DIR, exist_ok=True)
    os.makedirs(OUT_DIR, exist_ok=True)

    n = len(paths)
    rng = np.random.default_rng(seed)
    perm = rng.permutation(n)
    n_te = max(10, int(round(TEST_FRAC * n)))
    te_idx, tr_idx = perm[:n_te], perm[n_te:]

    # Cover features are computed once and reused for every payload.
    cov_paths, Xc, alphas_ref = [], [], []
    for i, p in enumerate(paths):
        c = os.path.join(WORK_DIR, f"c_{i:05d}.jpg")
        if not os.path.exists(c):
            prepare_cover(p, c)
        cov_paths.append(c)
        Xc.append(features(c))
        alphas_ref.append(nzac(jpeglib.read_dct(c).Y))
    Xc = np.array(Xc)
    nz = np.array(alphas_ref, dtype=float)
    if verbose:
        print(f"{n} images, {n_te} held out, mean nzAC={nz.mean():.0f}")

    per_payload, score_matrix = [], {}
    for pb in payload_bytes:
        t0 = time.time()
        alpha_i = 8.0 * pb / nz                      # per-image embedding rate
        Xs, ch = [], []
        for i, c in enumerate(cov_paths):
            s = os.path.join(WORK_DIR, "s_tmp.jpg")
            ch.append(embed(c, s, float(alpha_i[i]), embedder, seed=1000 + i))
            Xs.append(features(s))
        Xs = np.array(Xs)

        clf = train_detector(Xc[tr_idx], Xs[tr_idx], seed=seed)
        sc = np.ravel(clf.predict_confidence(Xc[te_idx]))
        ss = np.ravel(clf.predict_confidence(Xs[te_idx]))
        res = p_e_from_scores(sc, ss)
        score_matrix[pb] = {"cover": sc.tolist(), "stego": ss.tolist()}

        row = {"payload_bytes": pb,
               "alpha_mean": float(alpha_i.mean()),
               "changes_mean": float(np.mean(ch)),
               "n_test": int(n_te),
               **res,
               "seconds": round(time.time() - t0, 1)}
        per_payload.append(row)
        if verbose:
            print(f"  payload={pb:3d}B alpha={row['alpha_mean']:.3f} "
                  f"changes={row['changes_mean']:.0f} P_E={res['P_E']:.4f} "
                  f"({row['seconds']}s)", flush=True)

        with open(os.path.join(OUT_DIR, f"sweep_{embedder}.json"), "w") as f:
            json.dump({"per_payload": per_payload,
                       "scores": score_matrix,
                       "cover_size": COVER_SIZE, "qf": QF,
                       "q_step": Q_STEP}, f)

    return {"per_payload": per_payload, "scores": score_matrix}


# ---------------------------------------------------------------------------
# Paired inference
# ---------------------------------------------------------------------------

def paired_test(scores: dict, pb_a: int, pb_b: int) -> dict:
    """Wilcoxon signed-rank on within-image detector-score differences.

    The same test images carry both payloads, so image content cancels. The
    effect size is the matched-pairs rank-biserial correlation.
    """
    a = np.array(scores[pb_a]["stego"])
    b = np.array(scores[pb_b]["stego"])
    d = a - b
    nz_d = d[d != 0]
    if nz_d.size < 6:
        return {"pair": (pb_a, pb_b), "n": int(nz_d.size), "p": None}
    stat, p = stats.wilcoxon(a, b)
    pos = float(np.sum(stats.rankdata(np.abs(nz_d))[nz_d > 0]))
    total = float(np.sum(stats.rankdata(np.abs(nz_d))))
    return {"pair": (pb_a, pb_b),
            "n": int(nz_d.size),
            "median_diff": float(np.median(d)),
            "p": float(p),
            "rank_biserial": 2.0 * pos / total - 1.0}


def config_table(cfgs: list[AeadConfig], per_payload: list[dict]) -> list[dict]:
    """Read each AEAD configuration off the measured detectability curve."""
    pbs = np.array([r["payload_bytes"] for r in per_payload], dtype=float)
    pes = np.array([r["P_E"] for r in per_payload], dtype=float)
    order = np.argsort(pbs)
    pbs, pes = pbs[order], pes[order]
    out = []
    for c in cfgs:
        out.append({**asdict(c),
                    "total_bytes": c.total_bytes,
                    "forgery_bits": c.forgery_bits,
                    "P_E_interp": float(np.interp(c.total_bytes, pbs, pes))})
    return out

