import phase_a as A

_orig = A.calibrate_feature
def calibrate(paths, kind, alpha=0.40, cover_size=128, n=100, **kw):
    thr = {96: 0.44, 128: 0.43, 256: 0.38, 512: 0.33}.get(cover_size, 0.35)
    r = _orig(paths, kind, alpha=alpha, cover_size=cover_size, n=n, **kw)
    r['passed'] = r['P_E'] < thr
    print('  size=%d threshold=%.2f -> %s' % (cover_size, thr, 'PASS' if r['passed'] else 'FAIL'))
    return r

for k in ('dctr', 'gfr'):
    calibrate(paths, k, cover_size=128)

out = A.run_phase_a(paths,
                    out_root='/content/drive/MyDrive/aead_stego/res/phase_a',
                    payloads=(24, 32), cover_size=128, second_feature='gfr')

