import shutil, os, glob

SRC = '/content'
DST = '/content/drive/MyDrive/aead_stego'
os.makedirs(DST, exist_ok=True)

for name in ('aead_paired.py', 'phase_a.py', 'phase_b.py'):
    s = os.path.join(SRC, name)
    if not os.path.exists(s):
        print('MISSING:', name); continue
    shutil.copy(s, os.path.join(DST, name))
    ok = open(s).read() == open(os.path.join(DST, name)).read()
    print('%-16s %5d lines  saved=%s' % (name, len(open(s).read().splitlines()), ok))